function add(x){const z=x.q;lesson(x.m,x.id,x.t,x.intro,x.b.join('\n'),x.ex,x.when,x.trade,x.err,x.task,x.mem,z[0],z.slice(1,4),z[4],z[5],x.flow,x.lab||'',x.ref||'');const l=LESSONS.at(-1);l.depth=x.depth||'Core';l.newInV2=true;}
add({m:'foundation',id:'pacelc',t:'PACELC: partition ছাড়াও trade-off',intro:'শুধু network ভাঙলে নয়, সব ঠিক থাকলেও দূরের copy-এর confirmation-এর অপেক্ষা response ধীর করতে পারে।',b:['CAP partition-এর সময় availability বনাম consistency-এর সীমা বোঝায়। PACELC-এর সহজ পাঠ: Partition হলে A/C trade-off; Else normal operation-এ Latency/Consistency trade-off। এটি product বেছে নেওয়ার slogan নয়, নির্দিষ্ট operation-এর coordination cost ব্যাখ্যার lens।','এক region-এর local write দ্রুত হতে পারে। অন্য region-এ synchronous confirmation চাইলে round-trip time ও দূরের region-এর health নির্ভরতা যোগ হয়। একই product বিভিন্ন configuration/operation-এ ভিন্ন guarantee দিতে পারে। Read/write policy, replication mode ও conflict handling আলাদাভাবে লিখুন।'],ex:'Dhaka-এর user Singapore-এ profile update করেন। দূরের region-এর acknowledgement ছাড়া success দিলে দ্রুত response, কিন্তু failover-এ latest data হারানোর policy বুঝতে হবে। Both-region durability চাইলে latency বাড়তে পারে।',when:'Multi-region data store ও replication design-এ।',trade:'কম coordination দ্রুততা দেয়; stronger guarantee user-visible consistency ভালো করতে পারে কিন্তু waiting বাড়ায়।',err:'একটি database-কে চিরস্থায়ীভাবে “AP” লিখে সব operation-এর behaviour ধরে নেওয়া।',task:'Profile read এবং payment state update-এর normal ও partition condition-এর চারটি সিদ্ধান্ত লিখুন।',mem:'Partition-এর সময় A/C; স্বাভাবিক সময়েও L/C নিয়ে ভাবুন।',q:['PACELC-এর E কী বোঝায়?','Else: partition ছাড়া স্বাভাবিক operation','Encryption','Event queue',0,'Network partition না থাকলেও latency ও consistency-এর trade-off থাকতে পারে।'],flow:['Normal request','Coordination প্রয়োজন?','Local / remote wait','Guarantee ও latency']});
add({m:'network',id:'dns',t:'DNS resolution, records ও TTL',intro:'ফোনবুকে নাম থেকে number পাওয়া যায়; DNS নাম থেকে network address খুঁজে পেতে সাহায্য করে।',b:['Browser/OS cache, recursive resolver, root/TLD delegation ও authoritative nameserver—cache miss হলে এই chain-এর প্রয়োজনীয় অংশ resolve হয়। A/AAAA address, CNAME alias, MX mail routing, TXT verification-এর মতো আলাদা record type আছে। CNAME-কে IP record ভেবে বসবেন না।','TTL cached answer কতক্ষণ ব্যবহারযোগ্য তার নির্দেশ দেয়। DNS change সব client-এ এক মুহূর্তে পৌঁছায় না। Negative caching-এ missing name-ও কিছু সময় মনে থাকতে পারে। DNS failover existing TCP/WebSocket connection সরায় না; client reconnect ও resolver cache বিবেচনা করতে হয়।'],ex:'নতুন server-এ site নেওয়ার আগে DNS TTL কমিয়ে propagation window plan করা যায়। পুরোনো server কিছু সময় চালু রাখুন; “record বদলেছি” মানে সবাই নতুন server-এ এসেছে নয়।',when:'Custom domain, service discovery ও hosting migration-এ।',trade:'Short TTL change দ্রুত ছড়াতে পারে কিন্তু resolver traffic বাড়ে। Long TTL caching efficient, change ধীর।',err:'A record-এ https:// বা port বসানো; DNS TTL-কে instant failover guarantee বলা।',task:'নিজের domain-এর A/AAAA/CNAME ও authoritative resolver trace করুন। একটি migration timeline লিখুন।',mem:'নাম resolve হয়; connection তারপর হয়।',q:['DNS update হলে existing WebSocket সঙ্গে সঙ্গে নতুন server-এ যায়?','হ্যাঁ','না, existing connection আলাদা','শুধু TTL=1 হলে',1,'DNS নতুন lookup-এ প্রভাব ফেলে; live connection migration আলাদা।'],flow:['Local cache','Recursive resolver','Authoritative answer','TTL-cached address']});
add({m:'network',id:'transport',t:'TCP, UDP ও HTTP/1.1 থেকে HTTP/3',intro:'একটি request পাঠাতে “কথার format” ও “পৌঁছানোর transport”—দুই স্তর আলাদা।',b:['TCP ordered reliable byte stream, congestion control ও retransmission দেয়; application message boundary নিজে দেয় না। UDP datagram-এ সেই guarantee নিজে নেই। UDP ব্যবহারকারী application protocol প্রয়োজনমতো reliability implement করতে পারে। “UDP মানে সবসময় unreliable app” বলা ভুল।','HTTP/1.1-এ connection reuse থাকলেও parallelism-এর limits আছে। HTTP/2 একই TCP connection-এ multiplexed streams দেয়, তবে TCP packet loss সব stream-এ delay ফেলতে পারে। HTTP/3 QUIC over UDP ব্যবহার করে independent stream delivery উন্নত করে; encryption, network ও implementation constraints এখনও থাকে।'],ex:'ভিডিও call-এ late audio packet retransmit হয়ে পরে এলে usefulness কমতে পারে। Financial API-তে business-level acknowledgement ও idempotency এখনও লাগে, transport reliable হলেও।',when:'Protocol নির্বাচন ও network latency বোঝার সময়।',trade:'Multiplexing connection overhead কমাতে পারে; loss, proxies ও compatibility অনুযায়ী behaviour বদলায়।',err:'TCP success মানে payment database-এ commit হয়েছে ভাবা।',task:'একটি file download, voice call ও internal RPC-এর transport requirements আলাদা লিখুন।',mem:'Transport bytes পৌঁছায়; business success application জানায়।',q:['TCP কী guarantee নিজে দেয় না?','Business transaction committed','Ordered bytes','Retransmission behaviour',0,'Transport delivery ও database transaction আলাদা boundary।'],flow:['Application message','HTTP / other protocol','TCP বা QUIC/UDP','Application acknowledgement']});
add({m:'network',id:'protocol-choice',t:'REST, GraphQL ও gRPC: design নির্বাচন',intro:'Menu থেকে fixed item নেওয়া, নিজের combination চাওয়া ও typed internal order—তিনটির interface একই হতে হবে না।',b:['REST resource-oriented interface ও HTTP semantics ব্যবহার করতে পারে। GraphQL client-কে schema থেকে selected fields চাওয়ার সুযোগ দেয়; resolvers-এ N+1, query depth, authorization ও cost limit দরকার। gRPC protobuf contract ও streaming support দিয়ে internal typed communication-এ কার্যকর হতে পারে।','Versioning, backward-compatible schema evolution, deadlines, cancellation ও error mapping communication contract-এর অংশ। GraphQL-এর একটি endpoint থাকলেই monitoring সহজ নয়; operation-level metrics লাগবে। gRPC ব্যবহার করলেই network failure বা duplicate request দূর হয় না।'],ex:'Public booking CRUD REST-এ সহজ। Dashboard-এর বহু entity aggregation GraphQL দিয়ে করা যায়; read amplification পরীক্ষা করুন। Internal low-latency typed calls-এ gRPC বিবেচ্য, browser/client support পরিকল্পনাসহ।',when:'Client needs, team boundaries, tooling ও operational capacity ভিন্ন হলে।',trade:'Flexibility বনাম predictable cost; compact typed protocol বনাম integration simplicity।',err:'একটিকে সব system-এর universal replacement বলা।',task:'তিন API style-এ list booking, errors ও pagination-এর contract sketch করুন। কোনটি কেন নেবেন লিখুন।',mem:'Protocol নয়, consumer ও workload আগে।',q:['GraphQL-এ query cost controls কেন দরকার?','Client query অনেক resolver কাজ তৈরি করতে পারে','TLS বন্ধ থাকে','Database লাগে না',0,'এক request-এর ভেতরে অনেক expensive operation হতে পারে।'],flow:['Consumer requirement','Contract / schema','Authorization + limits','Observed API behaviour']});
add({m:'network',id:'gateway',t:'API gateway, BFF ও compatibility',intro:'প্রবেশদ্বারে পরিচয় পরীক্ষা হতে পারে; ভেতরের প্রতিটি ঘরের permission তারপরও আলাদা।',b:['Gateway TLS termination, route selection, authentication checks, quota ও request correlation centralize করতে পারে। Resource authorization backend-এও enforce করুন। BFF—Backend for Frontend—web/mobile-এর প্রয়োজন অনুযায়ী response aggregate করে; সব business logic gateway-তে জমাবেন না।','API evolution-এ additive fields, defaults, versioned breaking change, deprecation notice ও consumer contract tests ব্যবহার করুন। Retry body ও idempotency headers preserve করুন। Gateway logs-এ tokens/personal payload ফাঁস ঠেকান। Multiple gateway instances ও config rollout-ও reliability concern।'],ex:'Mobile home screen-এর ৫টি independent API call BFF aggregate করে। একটি optional recommendation fail হলে partial response দেওয়া যায়; payment status fail হলে default success দেওয়া যায় না।',when:'Multiple services, heterogeneous clients ও public integration।',trade:'Central control সুবিধা দেয় কিন্তু shared bottleneck ও change blast radius বাড়তে পারে।',err:'Gateway authentication পার হলেই সব service resource access allowed ধরা।',task:'Gateway বনাম booking service-এর দায়িত্ব লিখুন। একটি deprecated field সরানোর migration plan দিন।',mem:'Gateway entry সামলায়; domain service business rule সামলায়।',q:['Gateway-তে login যাচাই হয়েছে। Invoice ownership check লাগবে?','হ্যাঁ','না','শুধু CSS-এ',0,'Identity আর object-level permission আলাদা।'],flow:['Web / mobile','Gateway / BFF','Domain authorization','Compatible response']});
add({m:'network',id:'rate-algorithms',t:'Rate limiting: window, token ও leaky bucket',intro:'দরজায় কতজন ঢুকতে পারবেন, কত দ্রুত পারবেন, আর হঠাৎ ভিড় কতটা মেনে নেবেন—এই তিন প্রশ্ন আলাদা।',b:['Fixed window সহজ counter, কিন্তু boundary-তে দুই window-এর burst হতে পারে। Sliding log timestamps ধরে precise window দেয়, memory বেশি। Sliding counter দুই window-এর weighted estimate দেয়। Token bucket সময়ের সঙ্গে refill হয়, capacity পর্যন্ত burst allowance ধরে। Leaky bucket নির্দিষ্ট drain দিয়ে smoothing বোঝায়।','Key হতে পারে tenant/user/API key/IP। Shared NAT-এ IP-only policy নির্দোষ user block করতে পারে। Distributed limiter-এ refill+check+decrement atomic হতে হবে। Failure-এ fail-open বা fail-closed operation risk অনুযায়ী লিখুন। HTTP 429 ও retry guidance client-কে দিন।'],ex:'Capacity 5, refill 1 token/s। প্রথমে ৫টি immediate request নেয়, ষষ্ঠটি reject। ২ সেকেন্ড পরে ২টি token ফেরে; কিন্তু maximum ৫-এর বেশি জমে না।',when:'Login abuse, public APIs, costly report ও inference quota।',trade:'Precision, state size, burst tolerance ও coordination cost-এর মধ্যে নির্বাচন।',err:'প্রতিটি server-এর local limit-কে global tenant quota বলা।',task:'ল্যাবে token শেষ করুন, সময় এগোন, refill দেখুন। Fixed-window boundary burst-এর timeline আঁকুন।',mem:'Rate steady flow ঠিক করে; bucket capacity burst ঠিক করে।',q:['Token bucket capacity কী নির্ধারণ করে?','জমানো token ও burst allowance','শুধু TLS version','Database size',0,'Refill rate sustained rate; capacity accumulated burst সীমা।'],flow:['Client identity','Atomic refill + check','Allow / 429','Metrics + policy'],'lab':'token'});
add({m:'scaling',id:'scale-directions',t:'Vertical, horizontal scaling ও Amdahl’s Law',intro:'একজন দ্রুত কর্মী নেবেন, নাকি আরও কর্মী? কাজ ভাগ করা না গেলে শুধু কর্মী বাড়িয়ে লাভ সীমিত।',b:['Vertical scaling একটি machine-এর CPU/RAM/IO capacity বাড়ায়। Horizontal scaling instance বাড়ায়। Stateless work তুলনামূলক সহজে ভাগ হয়; shared state, serialization ও coordination limits থেকে যায়। Throughput scaling ও availability improvement একই guarantee নয়।','Amdahl’s Law-এর simplified bound: speedup = 1 / ((1−p)+p/n), p parallelizable fraction, n workers। এটি workload assumption, real benchmark নয়। Database locks, global mutex বা shared provider quota serial bottleneck তৈরি করতে পারে। Capacity পরিবর্তনের আগে saturation evidence দেখুন।'],ex:'কাজের ৮০% parallel হলে অসীম worker দিয়েও theoretical speedup সর্বোচ্চ ৫×। ১০টি web instance একই saturated DB-তে call করলে সেই bottleneck বাড়তে পারে।',when:'Capacity planning ও “আরও server” প্রস্তাব যাচাইয়ে।',trade:'Vertical সহজ কিন্তু machine ceiling ও failure concentration; horizontal flexible কিন্তু data coordination খরচ।',err:'দ্বিগুণ instance মানেই দ্বিগুণ throughput বলা।',task:'CPU-heavy worker ও transaction-heavy API-এর scaling constraints আলাদা লিখুন।',mem:'আরও server-এর আগে serial bottleneck খুঁজুন।',q:['২০% serial কাজ থাকলে unlimited parallelism-এর ideal speedup ceiling?','5×','20×','Unlimited',0,'1/0.2 = 5; workload assumptions অপরিবর্তিত থাকলে।'],flow:['Measure bottleneck','Scale up / out','Shared dependency limits','Load-test again']});
add({m:'scaling',id:'l4-l7',t:'L4 বনাম L7 balancing ও TLS termination',intro:'ডাকঘর শুধু address দেখে route করতে পারে; আর receptionist request-এর উদ্দেশ্য দেখে আলাদা desk-এ পাঠাতে পারে।',b:['L4 load balancer transport-level information যেমন IP/port/connection দেখে routing করে। L7 application-aware হয়ে HTTP path, host, headers বা cookies অনুযায়ী route করতে পারে। TLS কোথায় terminate হচ্ছে তার ওপর request inspect করার সুযোগ নির্ভর করে। TLS passthrough ও terminate/re-encrypt আলাদা topology।','Client identity propagate করতে trusted proxy chain ও forwarding-header policy দরকার। Untrusted X-Forwarded-For বিশ্বাস করলে rate limit/audit spoof হতে পারে। Connection-level balancing-এ দীর্ঘ HTTP/2 বা WebSocket connection workload অসমান রাখতে পারে।',],ex:'/api/* booking service, /media/* storage/CDN route L7-এ করা যায়। Encrypted payload inspect না করে TCP stream route করলে L4-এর approach প্রাসঙ্গিক।',when:'Network topology, TLS boundary ও routing requirements নির্ধারণে।',trade:'L7 richer policies দেয়, কিন্তু parsing/configuration overhead ও shared risk। L4 simpler routing দেয়, business-level rules কম।',err:'Load balancer থাকলেই সব backend encrypted বলা; termination-এর পর network path বাদ দেওয়া।',task:'Browser→LB→API path-এ encryption কোথায় শুরু/শেষ চিহ্নিত করুন। Header trust boundary লিখুন।',mem:'L4 connection দেখে; L7 application message বোঝে।',q:['HTTP path ধরে routing সাধারণত কোন layer?','L7','শুধু L4','DNS TTL',0,'Application-layer inspection প্রয়োজন।'],flow:['Client TLS','L4 passthrough / L7 terminate','Backend routing','Trusted identity headers']});
add({m:'scaling',id:'balancing-algorithms',t:'Round robin, weighted, least connections ও IP hash',intro:'সমান request count সবসময় সমান কাজ নয়। ছোট query আর মিনিটব্যাপী stream-এর খরচ ভিন্ন।',b:['Round robin পালাক্রমে instance বেছে নেয়। Weighted routing capacity অনুযায়ী share দেয়। Least connections সক্রিয় connection কম আছে এমন node নেয়, তবে connection count CPU work-এর নিখুঁত proxy নয়। IP hash affinity দেয়, কিন্তু NAT ও client concentration imbalance করতে পারে।','Request duration, instance heterogeneity ও session locality দেখে algorithm বেছে নিন। Consistent routing চাইলে node membership change-এর remapping ভাবুন। Sticky session failover-এ state হারানো বা hotspot-এর risk রাখে। Measured queue length বা response latency-based policy-তেও noisy metrics-এর feedback loop সামলাতে হয়।'],ex:'API A/B সমান; A-তে দীর্ঘ websocket, B-তে short REST। Round robin connection count সমান করলেও active work আলাদা। Separate pools/protocol-aware routing লাগতে পারে।',when:'Traffic shape ও backend capacity আলাদা হলে।',trade:'Simple policy operationally সহজ; adaptive policy ভালো utilization দিতে পারে কিন্তু stability ও measurement দরকার।',err:'Least connections সব workload-এ optimal বলা।',task:'৫টি long ও ১০টি short request-এর distribution তিন policy-তে কাগজে simulate করুন।',mem:'Request count নয়, কাজের ধরনও দেখুন।',q:['এক IP-এর পেছনে অনেক user থাকলে IP hash-এ কী হতে পারে?','এক backend-এ disproportionate load','Automatic DB sharding','Zero latency',0,'NAT ব্যবহারকারীদের একই hash target-এ জড়ো করতে পারে।'],flow:['Traffic characteristics','Choose routing policy','Observe utilization','Rebalance / isolate pools'],'lab':'balancer'});
add({m:'scaling',id:'health-failover',t:'Health checks, graceful draining ও failover',intro:'কর্মী উপস্থিত আছেন মানেই নতুন customer সামলানোর মতো প্রস্তুত নন।',b:['Liveness বলে process stuck কি না; readiness বলে traffic নিতে প্রস্তুত কি না। Startup probe slow initialization চলাকালে premature restart আটকাতে পারে। Shallow endpoint process দেখলেও business dependency-এর প্রয়োজনীয় readiness পরীক্ষা বাদ পড়তে পারে। আবার সব dependency liveness-এ দিলে অন্য service-এর outage-এ restart storm হতে পারে।','Health detection interval, timeout, threshold ও recovery hysteresis লিখুন। Deployment-এ readiness off → routing remove → in-flight drain → terminate। Endpoint removal ও active connection-এর behaviour proxy/client অনুযায়ী ভিন্ন। Failover-এ stale state/duplicates possible, তাই retry safety জরুরি।'],ex:'Worker heavy model load করছে, process alive কিন্তু inference-ready নয়। Readiness fail রেখে load শেষ হলে traffic নেওয়া যায়; indiscriminate liveness restart করলে কখনো warmup শেষই হবে না।',when:'Deployments, overloaded dependencies ও availability planning-এ।',trade:'Aggressive checks দ্রুত detect করে কিন্তু false positive বাড়াতে পারে। Slow checks outage detection দেরি করে।',err:'Health check green মানেই end-to-end business success guaranteed।',task:'এক backend বন্ধ করুন; detection delay ও failed request count মাপার test plan লিখুন।',mem:'Alive, ready, healthy user journey—এক নয়।',q:['Slow startup-এ কোন probe অতিরিক্ত restart কমাতে সাহায্য করে?','Startup probe','শুধু DNS','Cache TTL',0,'Startup handling initialization-এর জন্য সময় দেয়।'],flow:['Startup','Readiness on','Drain new traffic','Finish / terminate']});
add({m:'scaling',id:'stateless',t:'Stateless service ও shared state',intro:'যেকোনো counter একই order handle করতে পারলে counter বাড়ানো সহজ হয়।',b:['Stateless instance request-এর মধ্যে authoritative user/session/business state নিজ memory-তে নির্ভরযোগ্যভাবে ধরে না। State নেই এমন নয়—database, object storage বা shared session store-এ থাকে। Local cache পুনর্গঠনযোগ্য হতে পারে।','Request-এ প্রয়োজনীয় identity/context আসে, backend authoritative state পড়ে। File upload local disk-এ রেখে পরের request অন্য instance-এ গেলে missing file হতে পারে। Background job scheduling প্রতিটি API instance-এ চালালে duplicate run হতে পারে। External state store নিজেই capacity ও availability dependency।'],ex:'Session server A-এর memory-তে। পরের request B-তে গেলে logout মনে হয়। Shared session store বা validated access token flow নিয়ে affinity dependency কমানো যায়।',when:'Horizontal scaling, rolling deployment ও instance replacement।',trade:'Stateless application scaling সহজ; shared stores-এর latency, reliability ও cost design করতে হবে।',err:'JWT ব্যবহার করলেই সব application state stateless হয়ে গেছে বলা।',task:'নিজের app-এর local memory, disk ও cron state তালিকা করুন; authoritative আর disposable আলাদা করুন।',mem:'Instance বদলাতে পারে; প্রয়োজনীয় state টিকে থাকতে হবে।',q:['এক instance-এর local disk-এ user upload রাখলে ঝুঁকি?','অন্য instance file নাও পেতে পারে','সবসময় CDN copy করে','আরও secure হয়ে যায়',0,'Shared storage বা explicit routing ছাড়া locality problem থাকে।'],flow:['Any instance','Request identity','Shared authoritative state','Disposable local cache']});
add({m:'scaling',id:'session-design',t:'Session management, affinity ও revocation',intro:'Login-এর পর পরিচয়ের continuity রাখতে হয়; session কোথায় রাখছেন তা failover-এর behaviour বদলায়।',b:['Opaque session ID browser cookie-তে, session record server/shared store-এ। Token-based access-এ signed claims যাচাই হয়; session revocation, role change ও token expiry policy আলাদা। Sticky session মূলত routing affinity; authoritative security mechanism নয়।','Session creation-এ fixation prevention, login-এর পর rotation, idle/absolute expiry ও logout across devices ভাবুন। Shared store unavailable হলে কি access বন্ধ হবে? Sensitive action-এ re-authentication দরকার কি? Multi-tab refresh race ও cookie scope লিখুন।'],ex:'Admin role সরানোর পর পুরোনো long-lived JWT এখনও claim বহন করে। Short expiry, server-side policy lookup বা revocation mechanism requirement অনুযায়ী প্রয়োজন হতে পারে।',when:'Multi-instance app, enterprise access ও mobile refresh flow।',trade:'Central session control সহজ কিন্তু store dependency; self-contained token validation cheap কিন্তু instant revoke কঠিন।',err:'Sticky session-এ সব security ও persistence problem solved ধরা।',task:'Login→role change→logout all devices-এর sequence diagram করুন।',mem:'Affinity routing; session identity; revocation policy।',q:['Sticky session মূলত কী করে?','এক client-কে নির্দিষ্ট backend-এ route করে','সব token revoke করে','DB encrypt করে',0,'এটি routing affinity, সম্পূর্ণ authentication solution নয়।'],flow:['Login / rotate','Session / token issue','Validate + permissions','Expire / revoke']});
add({m:'scaling',id:'autoscaling',t:'Autoscaling, warmup, cold start ও hysteresis',intro:'ভিড় দেখার পর নতুন counter খুলতে সময় লাগে। Server-ও তৎক্ষণাৎ কাজের জন্য প্রস্তুত হয় না।',b:['Autoscaler CPU, queue age, RPS বা custom metric দেখে replica বদলায়। Target metric workload bottleneck-এর সঙ্গে মিলতে হবে। IO-bound service CPU কম থাকলেও slow হতে পারে। Desired capacity হিসাবের পরে provisioning, image pull, startup ও warmup delay থাকে।','Minimum/maximum instances, scale-up headroom, scale-down stabilization, cooldown ও graceful draining রাখুন। Frequent up/down oscillation thrashing তৈরি করে। Dependency quota ও database connection poolও বাড়তি instance-এ বাড়ে; autoscaling downstream capacity তৈরি করে না।'],ex:'প্রতি API pool ২০ DB connection; ৫ থেকে ৩০ instance হলে সম্ভাব্য ৬০০ connection। Database limit ৩০০ হলে API scale-out নতুন outage করতে পারে।',when:'Variable traffic ও background backlog-based capacity।',trade:'Idle cost কমে, তবে reaction delay এবং control-loop complexity বাড়ে। Scheduled baseline burst-এর আগে সহায়ক হতে পারে।',err:'CPU 70% একটি universal target; scale-to-zero-তে cold start latency বাদ দেওয়া।',task:'Peak event-এর আগে minimum capacity, warmup ও max DB connections হিসাব করুন।',mem:'Scaling একটি control loop; instant magic নয়।',q:['Replica বাড়ালে downstream connection count কী হতে পারে?','বাড়তে পারে','সবসময় কমে','অপরিবর্তিত guaranteed',0,'Per-instance pools যোগ হয়; shared limits যাচাই জরুরি।'],flow:['Measure relevant load','Desired replicas','Provision + warmup','Observe + stabilize'],'ref':'https://kubernetes.io/docs/concepts/workloads/autoscaling/horizontal-pod-autoscale/'});
add({m:'scaling',id:'nginx-practical',t:'Practical: Nginx balancing নিজে চালান',intro:'Diagram-এর তিনটি box সত্যিকারের process হলে routing-এর সীমাবদ্ধতা আরও স্পষ্ট হয়।',b:['ZIP-এর practical/compose.yaml-এ local-only demo: Nginx proxy, তিন API identity responder, Redis ও PostgreSQL। API responder শুধু নাম ফেরায়; এটি load balancing demonstration, database-backed full application নয়। Port 127.0.0.1-এ bind করা; production configuration হিসেবে deploy করবেন না।','docker compose up -d দিয়ে চালিয়ে local 8088 endpoint বারবার পড়ুন। Responses-এ api-a/api-b/api-c দেখুন। api-b stop করে আবার request দিন। Passive detection-এর প্রথম request fail হতে পারে; proxy retry ও idempotency policy আলাদা বিষয়। শেষ হলে stop; data মুছতে volumes remove করার প্রভাব আগে বুঝুন।'],ex:'Round robin-এ পরপর identity আলাদা হবে। least_conn configure করলে এই খুব ছোট response-এ ফলের পার্থক্য স্পষ্ট নাও হতে পারে; long request workload লাগতে পারে।',when:'Local routing, proxy config ও failure observation practice।',trade:'Toy responder repeatable; বাস্তব business latency বা production readiness প্রমাণ করে না।',err:'Compose demo production-এ credentials/network hardening ছাড়া তুলে দেওয়া।',task:'practical/README_BN.md-এর তিন experiment করুন। Actual output নিজের notes-এ রাখুন।',mem:'Box-কে process বানান, failure ঘটিয়ে দেখুন।',q:['Demo responder কি production API capacity প্রমাণ করে?','না','হ্যাঁ','Redis চালু থাকলে হ্যাঁ',0,'Workload representative নয়; এটি routing lab।'],flow:['Local client :8088','Nginx upstream','API A / B / C','Observed identity']});
add({m:'cache',id:'cache-layers',t:'Browser, edge, application ও database cache',intro:'একই বইয়ের কপি টেবিল, পাশের ঘর ও library-তে থাকতে পারে। কোন কপি expire হয়েছে বুঝতে layer আলাদা করুন।',b:['Browser private cache, CDN shared cache, reverse proxy cache, application local/Redis cache এবং DB buffer cache ভিন্ন স্তর। একটি layer hit হলে পরের layer-এর কাজ বাদ যায়। তাই low origin traffic মানেই user সর্বশেষ response পাচ্ছেন না।','Cache-Control max-age freshness lifetime; no-cache মানে reuse-এর আগে validation দরকার, “কখনো store করবে না” নয়। no-store storage নিষিদ্ধ করার directive। private shared cache-এ response রাখার বিরুদ্ধে নির্দেশ দেয়। ETag/If-None-Match conditional request-এ unchanged হলে 304 দিয়ে body transfer বাঁচতে পারে।'],ex:'Profile API-এর personalized response shared CDN key-তে রাখলে অন্য user-এর data leak হতে পারে। Static hash-named JS দীর্ঘ cache পেতে পারে; HTML-এর update policy আলাদা।',when:'Page performance, CDN rollout ও stale response debugging।',trade:'প্রতি cache layer origin load কমায়, কিন্তু freshness ও invalidation coordination কঠিন করে।',err:'Redis key delete করলেই browser/CDN-এর সব পুরোনো content সরবে বলা।',task:'এক request-এর response headers inspect করে cache layers আঁকুন। no-cache বনাম no-store নিজের ভাষায় লিখুন।',mem:'কপি যত স্তরে, freshness policy তত জায়গায়।',q:['Cache-Control no-cache সাধারণত কী বোঝায়?','Reuse-এর আগে validation','কখনো storage নয়','Infinite TTL',0,'no-store-এর সঙ্গে এটি আলাদা directive।'],flow:['Browser cache','CDN / proxy cache','Application cache','DB buffer / storage'],'ref':'https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/Caching'});
add({m:'cache',id:'cache-policies',t:'Cache-aside, read-through, write-through ও write-back',intro:'কপি পড়া/লেখার দায়িত্ব application নেবে, নাকি cache abstraction? এই ownership-ই pattern বদলায়।',b:['Cache-aside application miss পেলে DB পড়ে fill করে। Read-through-এ cache-facing abstraction নিজে data fetch manage করে। Write-through-এ write synchronousভাবে cache/data-store path দিয়ে persist হয়; exact failure semantics implementation অনুযায়ী। Write-back/behind আগে cache-এ accept করে পরে backing store-এ flush করে।','Write-back acknowledge করার আগে durable log না থাকলে process loss-এ acknowledged write হারাতে পারে। শুধু pattern নাম দিয়ে guarantee দাবি করবেন না। Flush ordering, retry, crash recovery ও read consistency contract প্রয়োজন। Write-around DB-তে লেখে, cache next read-এ fill হতে পারে।'],ex:'Frequently read catalog cache-aside-এ সহজ। Durable financial record-এর একমাত্র copy volatile write-back cache-এ রাখা গ্রহণযোগ্য নাও হতে পারে; durable source of truth আগে ঠিক করুন।',when:'Read/write ratio এবং staleness/durability requirements অনুযায়ী cache integration।',trade:'Synchronous persistence write latency বাড়ায়। Deferred persistence throughput বাড়াতে পারে কিন্তু recovery complexity আনে।',err:'Write-through মানেই cache/DB একসঙ্গে distributed transaction ছাড়া সবসময় atomic বলা।',task:'Write-এর আগে/মাঝে/পরে crash হলে প্রতিটি pattern-এ data কোথায় থাকে table করুন।',mem:'Cache pattern-এর সঙ্গে failure contract-ও বলুন।',q:['Volatile write-back cache crash-এর risk কী?','Not-yet-flushed acknowledged data হারাতে পারে','সব data automatically replicated','কেবল CSS সমস্যা',0,'Durability mechanism ছাড়া pending writes হারানোর সম্ভাবনা থাকে।'],flow:['Write request','Synchronous / deferred path','Cache + backing store','Ack ও crash recovery']});
add({m:'cache',id:'eviction',t:'LRU, LFU, TTL ও memory budget',intro:'ব্যাগ ছোট হলে নতুন বই নিতে পুরোনো বই নামাতে হয়। কোন বইটি নামাবেন সেটিই eviction policy।',b:['LRU least recently used entry বাদ দেয়। LFU least frequently used entry-কে প্রাধান্য দিতে পারে; ageing ও approximation implementation অনুযায়ী। TTL expiry সময় অনুযায়ী validity নির্ধারণ করে—memory-pressure eviction-এর সমার্থক নয়। একই key valid থেকেও eviction হতে পারে।','Capacity, payload size ও metadata overhead মাপুন। Large values cache ধরে রেখে অন্য hot keys সরাতে পারে। LRU sequential scan-এ cache pollution তৈরি করতে পারে। LFU পুরোনো জনপ্রিয় key ধরে রাখলে changing workload-এ adaptation দরকার। Redis policy approximation/configuration official docs দেখে বুঝুন।'],ex:'Capacity তিন। Access A,B,C,A,D। Exact LRU-তে B বাদ যায়, কারণ A সম্প্রতি পড়া হয়েছে। LFU-এর tie policy আলাদা হলে victim বদলাতে পারে।',when:'Memory-limited cache ও hit ratio tuning।',trade:'Policy computation/metadata cost এবং workload adaptation বনাম simplicity।',err:'TTL expire না হলে entry কখনো যাবে না বলা।',task:'LRU lab-এ A,B,C,A,D চাপুন। FIFO হলে কোন entry যেত তুলনা করুন।',mem:'Expiry সময় দেখে; eviction capacity দেখে।',q:['LRU capacity 3, sequence A B C A D; কে বাদ যায়?','B','A','D',0,'B সবচেয়ে কম recently accessed।'],flow:['Access key','Update recency / frequency','Capacity exceeded?','Select victim'],'lab':'eviction'});
add({m:'cache',id:'cdn',t:'CDN, edge caching ও cache keys',intro:'দূরের warehouse-এর বদলে পাশের দোকানে জনপ্রিয় জিনিস থাকলে delivery দ্রুত হয়।',b:['CDN edge content serve করে; miss হলে origin fetch হয়। Pull CDN demand-এ fetch করে; push/pre-warm strategy আগেই content পৌঁছাতে পারে। Cache key-তে host/path/query ও প্রয়োজনীয় variation কীভাবে অন্তর্ভুক্ত হয় বুঝুন। Compression/content negotiation-এ Vary policy দরকার হতে পারে।','Versioned asset URL deploy update সহজ করে। Purge instant global guarantee নয়; provider behaviour verify করুন। Private file-এর signed URL/cookie access policy এবং cached object-এর authorization মিলিয়ে নিন। Edge compute-এ auth logic থাকলেও source-of-truth update latency আলাদা।'],ex:'video-abc/v3/segment001 file immutable রাখা যায়। profile/current-এর personalized JSON ভুল public cache-এ দিলে serious exposure। CDN origin-down অবস্থায় stale serve করবে কি না আগে নির্ধারণ করুন।',when:'Static assets, global media ও geographic latency কমাতে।',trade:'Origin traffic কমে; egress/cache invalidation cost ও freshness complexity যোগ হয়।',err:'CDN dynamic private response safe ধরে configuration বাদ দেওয়া।',task:'Image, public article ও private export-এর cache key, TTL, auth ও invalidation table লিখুন।',mem:'User-এর কাছে কপি আনুন; ভুল user-কে কপি দেবেন না।',q:['Asset filename-এ content hash রাখার সুবিধা?','Version change-এ নতুন cache key','Automatic authorization','Zero storage',0,'Immutable versioned URLs stale asset update সহজ করে।'],flow:['User edge','Cache key + access policy','Edge hit / origin miss','TTL / purge / version']});
add({m:'cache',id:'redis-practical',t:'Practical: Redis cache-aside পরীক্ষা',intro:'Cache hit শুধু একটি সংখ্যা নয়—DB access, TTL ও invalidation একসঙ্গে দেখে বোঝা ভালো।',b:['প্রদত্ত practical lab-এ Redis private Compose network-এ থাকে। redis-cli দিয়ে SET key value EX seconds, GET ও TTL পরীক্ষা করুন। Demo DB data আলাদাভাবে পড়ুন; cache-aside behaviour browser lab বা নিজের application-এ implement করুন। Compose-এ Redis থাকা মানেই sample API স্বয়ংক্রিয়ভাবে cached নয়।','প্রথম miss, দ্বিতীয় hit, DB change, invalidation, expiry এবং Redis restart—প্রতিটি case লিখুন। Cache keys tenant-scoped রাখুন। Cache outage-এ bounded DB fallback ও short timeout দরকার। Production Redis durability, auth, eviction ও network security আলাদাভাবে configure করতে হয়।'],ex:'tenant:A:product:42 key value100 TTL20s। DB120 হলেও key invalidate না করলে TTL শেষ হওয়ার আগে100 পড়া সম্ভব। Cache reset করলে authoritative DB থেকে fill করতে হবে।',when:'Redis commands ও cache life cycle হাতে-কলমে শেখা।',trade:'Local single Redis সহজ lab; high availability বা production benchmark নয়।',err:'GET-এর missing result আর zero/empty valid value একই হিসেবে process করা।',task:'practical guide-এর TTL experiment করুন; application code-এ miss ও cached-empty আলাদা handle করার design লিখুন।',mem:'Commands শিখুন, data lifecycle যাচাই করুন।',q:['Compose-এ Redis service থাকলেই API cached?','না, application integration দরকার','হ্যাঁ','শুধু GET endpoint-এ',0,'Cache integration logic না থাকলে API Redis ব্যবহার করবে না।'],flow:['Read cache','Explicit miss handling','Read authoritative data','Set TTL + invalidation'],'lab':'cache'});
add({m:'data',id:'sql-nosql',t:'SQL বনাম NoSQL: access pattern দিয়ে নির্বাচন',intro:'খাতা flexible হওয়া আর হিসাব সঠিক থাকা বিপরীত নয়; database type নামেই সব guarantee বোঝা যায় না।',b:['Relational model structured relations, constraints ও joins-এ কার্যকর। NoSQL একটি umbrella: key-value, document, wide-column, graph ভিন্ন model। SQL মানেই scale হয় না বা NoSQL মানেই transactions নেই—দুটিই ভুল generalization। Product-specific guarantees যাচাই করুন।','Access pattern, transaction boundary, query flexibility, size, consistency, team skill ও operations দিয়ে সিদ্ধান্ত নিন। Flexible schema থাকলেও application-এর schema contract প্রয়োজন। Polyglot persistence একাধিক store-এর sync, backup ও migration দায়িত্ব বাড়ায়।'],ex:'Booking/payment-এর relations ও local transactions PostgreSQL-এ সহজ হতে পারে। Large session lookup key-value store-এ মানাতে পারে। Same data দুই store-এ থাকলে authoritative copy ও stale secondary view নির্ধারণ করুন।',when:'নতুন data workload বা existing store-এর measured limitation।',trade:'Query flexibility, predictable access, write scale ও operational cost তুলনা করুন।',err:'Traffic estimate ছাড়া fashionable database নির্বাচন।',task:'৩টি query, ২টি invariant ও ১টি recovery requirement লিখে দুটি store তুলনা করুন।',mem:'Database নাম নয়, access pattern ও guarantee বেছে নিন।',q:['NoSQL মানেই transactions নেই—বাক্যটি?','ভুল; product/configuration অনুযায়ী','সঠিক সবসময়','শুধু Redis-এর জন্য সঠিক',0,'Capability product-specific।'],flow:['Queries + invariants','Data model','Guarantees + limits','Measured store choice']});
add({m:'data',id:'nosql-models',t:'Key-value, document, wide-column ও graph',intro:'চাবি দিয়ে locker খোঁজা, একসঙ্গে document পড়া, partition ধরে rows পড়া ও সম্পর্কের পথ খোঁজা—চারটি কাজের model আলাদা।',b:['Key-value key lookup-এ স্বাভাবিক; secondary query দরকার হলে extra index design লাগে। Document nested aggregate একসঙ্গে পড়তে পারে; unbounded embedded array document বড় করে। Wide-column stores-এ partition key ও clustering/access pattern গুরুত্বপূর্ণ। Graph vertices/edges ও traversal-centric workload-এ উপযোগী হতে পারে।','Read/write amplification, hot partition ও consistency দেখুন। Query-first modeling-এ একই fact একাধিক projection-এ লাগতে পারে। Update propagation ও repair policy লিখুন। “Schema-less” store-এ validation/version migration বাদ যায় না।'],ex:'Chat message conversation_id partition ও sequence order-এ পড়া হয়। Unbounded conversation একটি partition-এ রাখলে বড়/hot হতে পারে; time bucket ও fan-out trade-off দেখুন।',when:'নির্দিষ্ট access shape relational query-এর চেয়ে অন্য model-এ ভালো মানালে।',trade:'Efficient predefined access বনাম ad-hoc query ও duplication cost।',err:'Document-এ সব relationship embed করে size ও concurrent update উপেক্ষা।',task:'User session, product catalog, chat history ও social relationship-এর store model নির্বাচন করে query দেখান।',mem:'কীভাবে পড়বেন, model তার সঙ্গে মিলুক।',q:['Graph store-এর স্বাভাবিক workload কোনটি?','Relationship traversal','শুধু CSS files','সব numeric addition',0,'Vertices ও edges ধরে paths/relationships query করা এর একটি লক্ষ্য।'],flow:['Lookup / aggregate / traversal','Choose model','Key ও partition','Query + update policy']});
add({m:'data',id:'btree-lsm',t:'B-tree বনাম LSM tree ও write amplification',intro:'প্রতিবার সাজানো বইয়ের সঠিক পাতায় লিখবেন, নাকি আগে দ্রুত নোট রেখে পরে গুছাবেন? Storage engine-এ এমন trade-off দেখা যায়।',b:['B-tree family balanced page structure দিয়ে point/range lookup ও ordered access সমর্থন করে। Page updates, splits ও buffering write path-এর অংশ। LSM design সাধারণত memory structure ও immutable sorted files ব্যবহার করে; flush/compaction পরে sorted data মেলায়। Implementations ভিন্ন।','LSM-এ write, read ও space amplification trade-off আছে। Bloom filter non-member key-এর unnecessary file checks কমাতে পারে, false positive সম্ভব কিন্তু normal correct implementation-এ false negative নয়। Deletes tombstone দিয়ে পরে compaction-এ পরিষ্কার হতে পারে। Compaction latency/IO budget গুরুত্বপূর্ণ।'],ex:'Sustained write-heavy log workload-এ LSM approach উপযোগী হতে পারে; read path-এ multiple files check ও compaction cost মাপতে হবে। B-tree ব্যবহৃত DB-তেও WAL ও buffer cache থাকে—তাই analogy-কে implementation specification ভাববেন না।',when:'Index/storage trade-off ও database performance বোঝা।',trade:'Write throughput বনাম read/space amplification; exact ফল workload/engine-dependent।',err:'LSM সব writes দ্রুত, সব reads ধীর—এমন absolute দাবি।',task:'এক update-এর WAL, memory, disk ও compaction path আঁকুন। Point/range reads-এর cost লিখুন।',mem:'Storage খরচ পড়া, লেখা ও গুছানো—তিন জায়গায় যায়।',q:['Bloom filter positive মানেই key অবশ্যই আছে?','না, false positive হতে পারে','হ্যাঁ','শুধু LRU হলে',0,'Positive lookup verify করতে হয়।'],flow:['Write + durability log','Memory / pages','Sorted disk structures','Compaction / lookup']});
add({m:'data',id:'consistent-hashing',t:'Consistent hashing ও virtual nodes',intro:'Server সংখ্যা বদলালে সব user-এর data location বদলাতে না চাইলে ring-based assignment কাজে আসতে পারে।',b:['Naive hash(key) mod N-এ N বদলালে অনেক mapping বদলায়। Consistent hashing node ও key-কে hash space/ring-এ বসিয়ে key-এর clockwise successor বেছে নিতে পারে। Node যোগ/বাদে প্রধানত সংশ্লিষ্ট ranges বদলায়। Exact movement distribution ও placement-এর ওপর নির্ভর করে।','Virtual nodes এক physical node-কে বহু ring position দেয়; balance ও heterogeneous weight manage করা সহজ হয়। Ownership বদলালেই stored bytes migrate হয় না—copy, replication ও routing version দরকার। একটি hot key তবুও এক owner-এ concentration আনতে পারে।'],ex:'৩ node-এর cache-এ node D যোগ করলেন। Lab-এ naive modulo ও ring-এর moved-key count তুলনা করুন। Synthetic hash/positions-এর ফলকে সব production workload-এর percentage বলবেন না।',when:'Distributed cache placement, sharding ও membership changes।',trade:'Limited remapping সুবিধা; placement, migration ও hotspot handling complexity।',err:'Consistent hashing data copy/replication-এর বিকল্প ভাবা।',task:'Ring lab-এ node যোগ/সরান। কোন keys move হলো এবং কেন তা দুই লাইনে লিখুন।',mem:'Mapping বদলানো কমে; migration নিজে হয় না।',q:['Virtual node-এর ভূমিকা কী?','এক physical node-এর একাধিক hash-space position','একই key-এর infinite copy','Consensus election',0,'এটি distribution/weighting-এ সাহায্য করে।'],flow:['Hash keys + virtual nodes','Clockwise owner','Membership change','Move affected ranges'],'lab':'hashing'});
add({m:'data',id:'hot-partitions',t:'Hot key, skew ও tenant placement',intro:'সব counter খালি, একটি counter-এ বিশাল line—average utilization misleading হতে পারে।',b:['Uniform key count সমান traffic নয়। Celebrity item, large tenant, time-prefix বা monotonically increasing key hotspot করতে পারে। Per-key/partition RPS, bytes, queue depth ও p99 দেখুন; শুধু average CPU নয়।','Read hot key replica/cache/coalescing দিয়ে mitigate হতে পারে। Write hot key split/salting/sharded counter দিয়ে ভাগ করা যায়, কিন্তু read merge ও exact total semantics কঠিন হয়। Large tenant আলাদা shard/pool-এ isolate করা বা capacity-weighted placement প্রাসঙ্গিক হতে পারে।',],ex:'Counter মোট ১০০ অংশে split করলে writes ভাগ হয়; exact current total পড়তে ১০০ অংশ merge করতে হবে। Approximate count চললে cached aggregate রাখা যায়।',when:'Uneven traffic, multi-tenant noisy neighbour ও write hotspots।',trade:'Splitting throughput বাড়াতে পারে, read fan-out ও correctness complexity যোগ করে।',err:'Data evenly sized মানেই traffic balanced।',task:'এক hot tenant traffic-এর ৭০% হলে route/data split plan এবং migration rollback লিখুন।',mem:'সমান data ≠ সমান কাজ।',q:['এক key খুব জনপ্রিয় হলে consistent hashing একাই কী করে?','Hotspot নিশ্চিতভাবে দূর করে না','প্রতি read zero cost','সব writes stop',0,'Key এখনও নির্দিষ্ট owner/policy-তে যায়।'],flow:['Detect skew','Classify read / write hot','Isolate / split / cache','Measure new bottleneck']});
add({m:'data',id:'object-storage',t:'Object storage, blobs, multipart ও lifecycle',intro:'বড় ফাইল database row-এ রাখতেই হবে না; কিন্তু file metadata ও permission তখনও design করতে হবে।',b:['Object storage key→bytes+metadata interface দেয়; সাধারণ filesystem-এর rename/locking/POSIX semantics ধরে নেবেন না। Store-specific consistency ও listing guarantees verify করুন। Relational DB-তে owner, status, object key, size ও checksum রাখা যায়।','Large upload multipart/resumable flow, completion verification, orphan cleanup, malware scan ও retention lifecycle দরকার। Signed URL bounded bearer access হতে পারে; expiry পর্যন্ত link share-এর প্রভাব বুঝুন। DB commit ও file upload আলাদা system, তাই pending/ready/deleted state ও reconciliation দরকার।'],ex:'Upload URL দেওয়ার পর user মাঝপথে চলে গেল। Pending metadata ও incomplete parts cleanup করুন। File পাওয়া গেলেই parsed/scan-ready বলা যাবে না।',when:'PDF, images, videos, model artifacts ও exports।',trade:'বড় bytes আলাদা scale সহজ; metadata consistency, lifecycle ও storage/egress cost যোগ হয়।',err:'Object URL random বলেই private ধরা।',task:'এক ২GB video upload-এর initialize/parts/complete/verify/scan/ready flow লিখুন।',mem:'Bytes, metadata, permission ও lifecycle আলাদা রাখুন।',q:['Upload success কি scan/processing success-এর সমান?','না','হ্যাঁ','File name ছোট হলে',0,'Readiness workflow আলাদাভাবে track করতে হয়।'],flow:['Authorize upload','Multipart object','Verify + scan','Ready / cleanup']});
add({m:'async',id:'rabbitmq',t:'RabbitMQ: exchange, queue, ack ও prefetch',intro:'কাজ কোথায় যাবে আর কোন worker নেবে—broker-এ routing ও consumption আলাদা দায়িত্ব।',b:['Producer exchange-এ publish করে; binding/routing key অনুযায়ী message queue-তে যায়। Direct, topic ও fanout exchange ভিন্ন routing দেয়। Consumer queue থেকে delivery পায়; manual acknowledgement processing ownership transfer-এর অংশ। Publisher confirms broker-এর acceptance জানায়; consumer business completion তার সমান নয়।','Durable topology, persistent messages ও appropriate replicated queue policy recovery-তে সাহায্য করতে পারে; প্রতিটির guarantee configuration-dependent। Prefetch unacked in-flight delivery সীমিত রাখে, slow consumer-এ অযথা কাজ আটকে যাওয়া কমাতে পারে। Crash-এর পরে redelivery duplicate করতে পারে।'],ex:'Invoice job worker PDF বানিয়ে object storage ready state লিখে ack দিল। File upload হলো কিন্তু ack-এর আগে crash—job আবার আসতে পারে। Stable job ID ও idempotent result path দরকার।',when:'Work queue, task routing ও bounded background processing।',trade:'Broker routing flexible; delivery/ack lifecycle ও queue monitoring operations বাড়ায়।',err:'Publisher confirm-কে email delivered বলা।',task:'এক job-এর publish/confirm/deliver/process/ack timeline লিখে প্রতিটি crash point দেখুন।',mem:'Publish accepted, worker received, business done—তিন ধাপ।',q:['Consumer prefetch মূলত কী সীমিত করে?','Unacknowledged in-flight deliveries','Daily DNS requests','Database schemas',0,'Consumer-এর pending delivery bound করতে সাহায্য করে।'],flow:['Producer → exchange','Bindings → queue','Consumer processing','Ack / redelivery'],'ref':'https://www.rabbitmq.com/docs/confirms'});
add({m:'async',id:'kafka',t:'Kafka: topic, log, retention ও replay',intro:'কাজ নিয়ে মুছে ফেলার queue আর নির্দিষ্ট সময় ধরে রাখা event log-এর ব্যবহারের ধরন আলাদা।',b:['Kafka topic partitioned append-only log হিসেবে ভাবা যায়। Producer records লিখে, consumer offset ধরে পড়ে। Retention policy বা compaction data কতটা রাখবে তা নির্ধারণ করে; consumer পড়েছে বলেই record সঙ্গে সঙ্গে মুছে যায় না।','Consumer group একই workload ভাগ করে; আলাদা group independent processing/replay করতে পারে। Committed offset restart position বোঝায়। Process→commit crash-এ duplicate হতে পারে; commit→process crash-এ work miss হওয়ার risk। Transactional semantics-এর boundary external database/side effect পর্যন্ত নিজে ধরে নেবেন না।'],ex:'Order events billing ও analytics-এর আলাদা group পড়ে। Analytics নতুন projection rebuild করতে retained history replay করতে পারে; retention-এর বাইরে হারানো history automatic ফিরে আসে না।',when:'Event streaming, multiple independent consumers, replay ও ordered partition processing।',trade:'Retained log reprocessing দেয় কিন্তু storage, schema evolution ও consumer lag operations লাগে।',err:'Kafka ব্যবহারে সব external side effect exactly once হয় বলা।',task:'এক topic, দুই partition, দুই consumer group-এর offsets diagram করুন।',mem:'Log থাকে; প্রতিটি group নিজের position রাখে।',q:['এক group-এর consumption অন্য group-এর offset advance করে?','না','হ্যাঁ','শুধু JSON হলে',0,'Groups আলাদা progress রাখে।'],flow:['Producer events','Partitioned retained log','Independent groups','Offset + replay'],'ref':'https://kafka.apache.org/41/design/design/'});
add({m:'async',id:'kafka-partitions',t:'Kafka internals: keys, partitions, groups ও rebalancing',intro:'এক partition-এর ক্রম আছে; একাধিক partition-এর মধ্যে স্বয়ংক্রিয় global order নেই।',b:['Record key partition selection-এ ব্যবহার হতে পারে; একই key-এর logical order প্রয়োজন হলে producer partitioning ও partition count change-এর প্রভাব বুঝুন। Conventional consumer-group assignment-এ এক partition একই সময়ে এক consumer-কে assigned থাকে; বেশি consumers সবসময় বেশি parallelism দেয় না।','Partition leader, follower replication, in-sync replicas ও acknowledgement configuration durability/availability বদলায়। Leader failover-এর policy data loss risk-এ প্রভাব ফেলে। Consumer membership বদলালে rebalance work ownership বদলায়; pending work, duplicate processing ও pause time handle করুন।'],ex:'৩ partition-এর group-এ ৫ consumer হলে conventional assignment-এ সর্বোচ্চ ৩ consumer partition ownership পেতে পারে। একটি partition-এর hot key capacity পুরো group সীমিত করতে পারে।',when:'Streaming system capacity, ordering ও failure analysis।',trade:'বেশি partition parallelism দেয় কিন্তু metadata, ordering scope, rebalance ও operational cost বাড়ায়।',err:'এক topic-এর সব record total ordered বলা।',task:'Per-order ordering বজায় রেখে ১০,০০০ order events distribute করার key strategy লিখুন।',mem:'Key locality, partition order, group ownership।',q:['Kafka-এর ordering সাধারণত কোন scope-এ?','Partition-এর মধ্যে','সব topic মিলে globally','সব consumer application-এর মধ্যে',0,'Cross-partition global order নিজে আসে না।'],flow:['Event key','Partition owner','Replicated log','Consumer + checkpoint']});
add({m:'async',id:'pubsub',t:'Pub/Sub, fan-out ও durable subscribers',intro:'একটি ঘোষণা বহু team শুনতে চায়; সবার কাজের status এক queue-এর shared progress নয়।',b:['Pub/sub এক event বহু subscriber-এ দেয়। Work queue-তে workers সাধারণত একই কাজ ভাগ করে। Product অনুযায়ী ephemeral pub/sub ও durable subscription ভিন্ন; disconnected subscriber event হারাতে পারে বা retained history থেকে catch up করতে পারে।','Fan-out-এর সময় subscriber list, permission, backpressure ও per-subscriber retry policy দরকার। Slow analytics যেন critical billing delivery আটকে না দেয়। Notification service-এ channel-specific queue এবং priority pool রাখা যায়।'],ex:'OrderCreated billing, inventory ও analytics শুনবে। তিন consumer একই competing work queue পড়লে প্রতিটি event তিনজনই পাবে—এই assumption ভুল হতে পারে। আলাদা durable subscriptions/queues প্রয়োজন।',when:'Independent reactions, event notification ও realtime gateway routing।',trade:'Loose coupling বাড়ে কিন্তু event ownership, duplicate এবং observability জটিল হয়।',err:'Redis Pub/Sub-কে durable message archive ধরা।',task:'এক event তিন team-এ পৌঁছানোর topology আঁকুন। এক subscriber এক ঘণ্টা offline হলে policy লিখুন।',mem:'Broadcast আর কাজ ভাগ করা এক নয়।',q:['সব subscriber-কে একই event দিতে topology কী ভাববে?','Independent subscription/fan-out','শুধু এক competing queue','শুধু one worker',0,'Competing consumption প্রতিটি worker-কে সব event দেয় না।'],flow:['Event','Subscriber routing','Independent delivery state','Retry / catch-up']});
add({m:'async',id:'event-architecture',t:'Event-driven architecture, schemas ও CQRS',intro:'“ঘটেছে” এমন fact প্রকাশ করা আর “এখন করো” এমন command পাঠানো আলাদা কথা।',b:['Event past fact, যেমন BookingConfirmed। Command intent, যেমন ConfirmBooking; reject হতে পারে। Schema-তে event ID, entity ID, version, timestamp ও trace/tenant context দরকারমতো রাখুন। Consumer-কে publisher-এর private DB schema-তে tightly couple করবেন না।','CQRS read/write model আলাদা করতে পারে; একই DB-তেও সম্ভব। Event sourcing state পরিবর্তনের authoritative event history রাখে—এটি CQRS বা event-driven-এর বাধ্যতামূলক অংশ নয়। Projections rebuild, schema evolution, replay side effects ও data deletion policy কঠিন হতে পারে।'],ex:'BookingConfirmed থেকে dashboard read model update হয়। Projection delay হলে dashboard পুরোনো হতে পারে; final booking success write model-এর result থেকে আসবে।',when:'Multiple reactions, independent read models ও asynchronous workflows।',trade:'Decoupling ও read optimization; debugging, ordering ও eventual consistency cost।',err:'সব CRUD-এর জন্য event sourcing বাধ্যতামূলক করা; replay-এ আবার external email পাঠানো।',task:'এক event schema-এর additive version change ও পুরোনো consumer behaviour লিখুন।',mem:'Event fact; command intent; projection কপি।',q:['CQRS মানেই event sourcing?','না','হ্যাঁ','শুধু Kafka হলে',0,'দুটি আলাদা architectural ধারণা।'],flow:['Command + invariant','Committed fact','Event distribution','Read projections']});
add({m:'distributed',id:'partial-failure',t:'Partial failures, timeout ambiguity ও retry budgets',intro:'ফোনে “শুনতে পাচ্ছি না” মানে অন্যজন আপনার কথা শোনেননি—এটি নিশ্চিত নয়।',b:['এক অংশ healthy, আরেক অংশ slow/down—distributed system-এ partial failure সাধারণ। Request server-এ complete হয়ে response হারাতে পারে। Timeout outcome unknown জানায়; failure নিশ্চিত করে না। Request deadline পুরো chain-এ propagate করলে user চলে যাওয়ার পরও অযথা work কমে।','Bounded retries, exponential backoff, jitter, retry budget ও idempotency একসঙ্গে ভাবুন। পাঁচ layer প্রত্যেকে তিন attempt করলে worst case fan-out 3^5 হতে পারে। Retry একটি নির্বাচিত layer-এ centralize করা যুক্তিযুক্ত হতে পারে। Load shedding/partial response criticality অনুযায়ী ব্যবহার করুন।'],ex:'Payment provider timeout-এর পরে আবার নতুন transaction না খুলে একই idempotency intent দিয়ে status query বা safe retry করুন। External outcome pending state-এ রেখে reconcile করুন।',when:'যেকোনো remote dependency ও distributed workflow।',trade:'Retry recovery সাহায্য করে কিন্তু overload ও duplicate risk বাড়ায়।',err:'Timeout হলে নিশ্চিত refund বা নতুন charge করা।',task:'এক request commit-এর আগে ও পরে response loss-এর দুটি timeline লিখুন।',mem:'Timeout বলে জানি না; idempotency ও reconciliation দিয়ে জানব।',q:['Timeout-এর পরে operation outcome সাধারণত?','Unknown হতে পারে','অবশ্যই failed','অবশ্যই rolled back',0,'Server complete করলেও response পথে হারাতে পারে।'],flow:['Call + deadline','Outcome uncertain','Bounded safe retry','Query / reconcile']});
add({m:'distributed',id:'quorum',t:'Quorum: R + W > N এবং সীমাবদ্ধতা',intro:'কয়েকটি copy থেকে পড়া-লেখার সেট overlap করলে latest তথ্য খোঁজার সুযোগ হয়; কিন্তু overlap একাই সব consistency guarantee নয়।',b:['N replicas, W required write acknowledgements, R read responses। Fixed replica set-এ R+W>N হলে যেকোনো read/write quorum-এর overlap থাকে। W>N/2 হলে write quorums-ও overlap করে। এই arithmetic network বা concurrent writes নিজে resolve করে না।','Version comparison, concurrent write resolution, membership changes, stale responses, sloppy quorum, repair ও protocol semantics গুরুত্বপূর্ণ। Quorum overlap alone linearizability প্রমাণ নয়। Read repair/anti-entropy convergence সহায়ক হতে পারে; exact guarantee implementation-dependent।'],ex:'N=3,W=2,R=2-এ overlap বাধ্যতামূলক। একটি node unreachable হলেও quorum সম্ভব। N=3,W=1,R=1-এ read latest write পাওয়া নিশ্চিত নয়।',when:'Replicated store-এর read/write policy বোঝা।',trade:'বড় R/W coordination ও latency বাড়াতে পারে; unreachable replicas-এ availability কমে।',err:'R+W>N দেখিয়েই all operations strongly consistent দাবি।',task:'ল্যাবে R/W/N বদলান। Read set এবং write set নিজে এঁকে overlap দেখান।',mem:'Overlap দরকার হতে পারে; protocol-ও সঠিক হতে হবে।',q:['R+W>N একাই linearizability guarantee?','না','হ্যাঁ','N=3 হলে হ্যাঁ',0,'Concurrency, versioning ও protocol semantics-ও প্রয়োজন।'],flow:['Replica set N','Write quorum W','Read quorum R','Version + conflict rules'],'lab':'quorum'});
add({m:'distributed',id:'raft',t:'Raft consensus: terms, log replication ও commit',intro:'কে leader তা ঠিক করা আর কোন পরিবর্তন সবাই গ্রহণ করল তা ঠিক করা—সম্পর্কিত কিন্তু পৃথক কাজ।',b:['Raft nodes follower/candidate/leader role-এ থাকে। Term monotonically বাড়ে; election-এ একই term-এর majority votes লাগে। Leader log entry replicate করে এবং protocol-এর commit rules অনুযায়ী committed entries state machine-এ apply হয়। শুধু leader memory-তে লেখা success-এর যথেষ্ট প্রমাণ নয়।','Log matching ও leader completeness safety rules history consistency বজায় রাখে। Majority available না থাকলে progress থামতে পারে, safety তবুও রক্ষার লক্ষ্য। পাঁচ node quorum cluster সাধারণ non-Byzantine assumptions-এ দুই node unavailable সহ progress করতে পারে, network conditions ও configuration মিলে গেলে। Raft malicious Byzantine behaviour tolerate করার protocol নয়।'],ex:'৫ node-এ isolated দুইজন majority পায় না। অন্য তিনজন leader নির্বাচন করে committed log এগোতে পারে। Disconnected পুরোনো leader-কে authoritative নতুন writes accept করতে দেওয়া যাবে না।',when:'Consensus-backed configuration/metadata stores ও coordination systems বোঝা।',trade:'Strong agreement coordination latency ও quorum availability চায়।',err:'Raft মানে সব read automatically linearizable; read protocol/configuration না দেখা।',task:'৫ node-কে 3/2 ভাগ করে কোন পাশে progress সম্ভব ব্যাখ্যা করুন।',mem:'Majority + terms + log rules মিলে consensus।',q:['৫ node-এর majority কত?','3','2','5 সবসময়',0,'Half-এর বেশি: floor(5/2)+1 = 3।'],flow:['Election term','Majority leader','Replicate log','Commit + apply'],'depth':'Advanced concept','ref':'https://raft.github.io/raft.pdf'});
add({m:'distributed',id:'leader-election',t:'Leader election, split brain ও fencing',intro:'দুজন একসঙ্গে নিজেকে manager ভাবলে একই resource-এ conflicting নির্দেশ যেতে পারে।',b:['Leader election একটি coordinator নির্বাচন করে। Heartbeat হারালে node dead নাও হতে পারে; network delay/process pause হতে পারে। Randomized election timeout split votes কমাতে পারে, তবু protocol safety আলাদা rules দিয়ে আসে।','Lease নির্দিষ্ট সময় ownership দেয়, clock/delay assumptions থাকতে পারে। পুরোনো leader pause থেকে ফিরে stale action করলে resource-এর fencing token check তা reject করতে পারে। Token নতুন owner-এর সঙ্গে monotonically বাড়ে এবং downstream protected resource-এ enforce করতে হয়; শুধু log-এ token লেখা যথেষ্ট নয়।'],ex:'Scheduler worker A-এর lease expire, B নতুন token8 পায়। A token7 নিয়ে storage update করতে গেলে storage reject করবে। Storage token না দেখলে lease alone stale write আটকায় না।',when:'Schedulers, singleton job, shared resource ownership।',trade:'Coordination correctness সাহায্য করে; dependency outage-এ কাজ থামতে পারে।',err:'একটি Redis lock মানেই সব process pause/partition-এ exclusive external effect guaranteed।',task:'পুরোনো leader pause ও resume-এর timeline-এ fencing কোথায় enforce হবে আঁকুন।',mem:'Leader বদলালেই পুরোনো হাত থামে না; fence লাগতে পারে।',q:['Fencing token কে যাচাই করবে?','Protected resource / write boundary','শুধু UI','শুধু timestamp label',0,'Resource stale token reject না করলে protection কার্যকর হয় না।'],flow:['Acquire ownership','New fencing token','Protected write','Reject stale owner']});
add({m:'distributed',id:'two-phase-commit',t:'2PC: prepare, commit ও in-doubt state',intro:'দুটি খাতায় একসঙ্গে সিদ্ধান্ত নিতে চাইলে সবাই প্রস্তুত কিনা এবং final সিদ্ধান্ত কী—দুটি ধাপ লাগে।',b:['Two-phase commit-এ coordinator participants-কে prepare জিজ্ঞেস করে। Participants local resources reserve/log করে yes/no জানায়। সবাই প্রস্তুত হলে coordinator durable decision নিয়ে commit জানায়, নইলে abort। Atomic commitment নির্দিষ্ট participants/protocol assumptions-এর scope-এ।','Prepare-এর পরে decision জানা না গেলে participant in-doubt হয়ে locks/resources ধরে রাখতে পারে। Coordinator recovery, durable logs ও timeout protocol গুরুত্বপূর্ণ। Arbitrary payment/email provider সাধারণত আপনার DB transaction-এর participant নয়। Consensus ও 2PC আলাদা problem; consensus-backed coordinator থাকলেও সব integration transactional হয়ে যায় না।'],ex:'দুটি transactional DB participant একই transfer-এ prepare হলো। Coordinator হারালে recovery পর্যন্ত অংশগ্রহণকারী অপেক্ষা করতে পারে। এর সঙ্গে external shipment rollback সম্ভব ধরে নেওয়া যাবে না।',when:'Supported distributed transaction environment-এর trade-off বোঝা।',trade:'Atomic decision বনাম blocking/latency/coordination cost।',err:'2PC ও saga একই; অথবা timeout হলেই participant independently commit করতে পারে ভাবা।',task:'Prepare-এর আগে ও পরে coordinator crash হলে participant state লিখুন।',mem:'Prepare-এ প্রতিশ্রুতি; decision না জানা পর্যন্ত uncertainty।',q:['2PC prepare-এর পরে coordinator হারালে কী ঝুঁকি?','In-doubt blocking','সবসময় instant commit','সব locks নিজে safe release',0,'Protocol/recovery decision ছাড়া participant অপেক্ষায় থাকতে পারে।'],flow:['Prepare request','Participants vote','Durable decision','Commit / abort'],'depth':'Advanced concept'});
add({m:'distributed',id:'clocks-locks',t:'Logical clocks, causality ও distributed locks',intro:'দুটি ঘড়ি মিললেই ঘটনা কোনটি অন্যটির কারণ তা জানা যায় না।',b:['Wall-clock timestamp human time দরকারে উপযোগী কিন্তু skew/rollback থাকে। Lamport clock causal order হলে timestamp order রাখতে পারে; বিপরীত inference সবসময় সত্য নয়। Vector clocks concurrent versions শনাক্তে সাহায্য করতে পারে, metadata cost বাড়ে। Per-entity sequence অনেক practical workflow-তে যথেষ্ট।','Distributed lock ব্যবহারে expiry, renewal, process pause, ownership verification ও downstream fencing ভাবুন। Critical correctness যদি DB constraint/atomic update-এ করা যায়, শুধু lock layer দিয়ে জটিল করবেন না। Lock release-এ ownership token মেলানো জরুরি; অন্যের নতুন lock delete করবেন না।'],ex:'A lock নিয়ে pause হলো; TTL শেষ, B lock পেল। A ফিরে এসে blind delete করলে B-এর lock মুছতে পারে। Compare-owner-and-delete atomic operation প্রয়োজন।',when:'Cross-node coordination, version conflicts ও sequencing।',trade:'More ordering metadata/coordination মানে complexity; প্রয়োজনের চেয়ে global order চাইবেন না।',err:'সব distributed race-এর universal solution lock।',task:'এক lease expiry race-এ lock ownership, token ও database guard লিখুন।',mem:'সময়, causal order ও ownership—আলাদা guarantee।',q:['Lamport timestamp কম মানেই সবসময় eventটি অন্যটির causal predecessor?','না','হ্যাঁ','শুধু UUID হলে',0,'Causality implies clock order, কিন্তু clock order causality প্রমাণ করে না।'],flow:['Concurrent events','Clock / version metadata','Ownership lease','Guard + fencing'],'depth':'Advanced concept'});
add({m:'operations',id:'discovery',t:'Service discovery ও dynamic endpoints',intro:'নতুন counter চালু হলে তার ঠিকানা জানা এবং বন্ধ counter-এ না যাওয়া—দুটিই দরকার।',b:['Service instances ephemeral হতে পারে। Registry বা DNS/service abstraction logical name থেকে healthy endpoints দেয়। Client-side discovery client list থেকে target নেয়; server-side discovery proxy/load balancer সেই দায়িত্ব নেয়। Registration, heartbeat, deregistration ও stale cache behaviour লিখুন।','Discovery-এর সঙ্গে health/connection lifecycle এক করুন। DNS cache পুরোনো endpoint ধরে রাখতে পারে; existing connections drain করতে হয়। Discovery store unavailable হলেও cached endpoints কিছু সময় চলতে পারে, কিন্তু safety/freshness policy স্পষ্ট দরকার।',],ex:'Report worker নতুন instance যোগ হলো। API hard-coded IP না ধরে reports.service logical address ব্যবহার করে। Deployment-এর পরে old IP cached থাকলে কিছু request fail করতে পারে।',when:'Autoscaling, orchestration ও multi-service environments।',trade:'Dynamic routing flexibility দেয়; discovery availability ও stale membership problem আনে।',err:'IP জানা মানেই application ready।',task:'Instance start/ready/stop-এর registry update ও client cache timeline আঁকুন।',mem:'ঠিকানা জানুন, readiness দেখুন, পুরোনো connection সামলান।',q:['Discovery প্রধানত কোন প্রশ্নের উত্তর দেয়?','Service instance কোথায়','User salary কত','Transaction rollback হবে কি',0,'Identity/address resolution ও membership-এর কাজ।'],flow:['Logical service name','Discovery / registry','Healthy endpoints','Client / proxy selection']});
add({m:'operations',id:'circuit-breaker',t:'Circuit breaker, bulkhead ও retry isolation',intro:'এক supplier বারবার ব্যর্থ হলে প্রতিটি নতুন customer-কে একই অপেক্ষায় আটকে রাখা বুদ্ধিমানের নয়।',b:['Circuit closed-এ calls যায় ও failures count হয়। Threshold পেরোলে open-এ fail-fast/fallback। Cooldown শেষে half-open-এ সীমিত probe; success হলে closed, failure হলে আবার open। Sliding window, minimum sample ও slow-call policy configuration অনুযায়ী।','Bulkhead আলাদা thread/connection/concurrency pool রাখে, যাতে noncritical report সব resources খেয়ে payment বন্ধ না করে। Timeout অপেক্ষা bound করে, retry transient failure সামলায়, circuit repeated pressure কমায়—এগুলো পরস্পরের বিকল্প নয়। Fallback stale/partial হতে পারে; মিথ্যা business success নয়।'],ex:'Recommendation provider down। Circuit open হলে homepage recommendation ছাড়া চলতে পারে। Payment provider down হলে “paid” fake fallback নয়; pending/unavailable status দেখান।',when:'Remote dependency failures ও cascading outage prevention।',trade:'Fail-fast resource বাঁচায় কিন্তু threshold ভুল হলে healthy dependency-ও বাদ যেতে পারে।',err:'Circuit open হলেই dependency recover হয়েছে ধরে নেওয়া; unlimited half-open probes।',task:'ল্যাবে failures দিয়ে circuit open করুন, cooldown ও probe চালান।',mem:'Wait bound, retries bound, failure spread bound।',q:['Half-open state-এর উদ্দেশ্য?','সীমিত recovery probe','সব traffic flood','Data delete',0,'Dependency recovery পরীক্ষা করতে controlled requests যায়।'],flow:['Closed: calls','Failure threshold','Open: reject','Half-open probe'],'lab':'breaker'});
add({m:'operations',id:'service-mesh',t:'Service mesh, mTLS ও traffic policy',intro:'প্রতিটি service নিজে transport policy implement করতে পারে; mesh সেই সাধারণ দায়িত্ব proxy/infra-তে নিতে পারে।',b:['Service mesh service-to-service identity, mTLS, routing, telemetry ও কিছু resilience policy manage করতে পারে। Sidecar বা অন্য data-plane model implementation-dependent। Control plane config/identity distribution করে; data plane traffic path-এ কাজ করে।','mTLS peer identity/encryption দেয়; business resource authorization নিজে পূরণ করে না। Mesh retries application retries-এর সঙ্গে multiply করতে পারে। Certificate rotation, proxy overhead, version compatibility ও debugging plan দরকার। Small monolith-এ mesh প্রয়োজন নাও হতে পারে।'],ex:'Service A শুধু B-কে call করতে পারবে policy mesh-এ। B-এর user invoice permission application-এ check হবে। Mesh trust identity আর end-user authority মিশিয়ে ফেলবেন না।',when:'বড় service estate-এ consistent transport/security operations-এর বাস্তব প্রয়োজন।',trade:'Common controls centralize হয়; proxy, control plane ও operational complexity বাড়ে।',err:'Mesh install করলেই distributed system reliable/secure সম্পূর্ণ হয়ে গেছে ভাবা।',task:'Application, gateway ও mesh-এর authorization/retry দায়িত্ব আলাদা table লিখুন।',mem:'Mesh transport সামলায়; business rule application-এ।',q:['mTLS একাই invoice ownership যাচাই করে?','না','হ্যাঁ','শুধু GraphQL-এ',0,'Peer identity ও object permission আলাদা।'],flow:['Service identity','Mesh data plane','mTLS + routing policy','Application authorization'],'depth':'Advanced concept'});
add({m:'operations',id:'kubernetes',t:'Kubernetes basics: Pods, Deployment, Service ও probes',intro:'Container একটি package; একাধিক machine-এ desired state বজায় রাখা orchestration-এর কাজ।',b:['Pod scheduling-এর ছোট unit। Deployment replicas/rollout ধরে; Service stable discovery/routing abstraction দেয়। Ingress বা Gateway ecosystem HTTP entry manage করতে পারে। ConfigMap/Secret configuration ধরে; Secret নাম মানেই encryption policy পূর্ণ নয়। PersistentVolume data lifecycle আলাদা রাখে।','Requests scheduler-এর capacity planning-এ, limits runtime boundary-তে ভূমিকা নেয়। Readiness, liveness ও startup probes আলাদা করুন। HPA metrics অনুযায়ী replica বদলায়; node capacity না থাকলে Pods pending হতে পারে। Graceful termination ও disruption planning দরকার।'],ex:'Deployment replica3 চাইছে, node-এ যথেষ্ট memory না থাকলে ৩টি healthy Pod পাওয়া যাবে না। HPA replica বাড়ানো আর node autoscaling আলাদা control loop।',when:'Containers-এর বহু instance/rollout manage করার প্রয়োজন হলে।',trade:'Automation ও recovery আসে; cluster operations ও configuration complexity বাড়ে।',err:'Kubernetes backup strategy-এর বিকল্প; সব app-এ প্রথম দিন cluster বাধ্যতামূলক।',task:'এক stateless API-এর Deployment, Service, readiness ও resource budget sketch করুন।',mem:'Desired replicas ≠ ready capacity; state আলাদাভাবে রক্ষা করুন।',q:['Pod readiness fail হলে সাধারণত লক্ষ্য কী?','নতুন traffic না দেওয়া','সঙ্গে সঙ্গে data delete','সব node reboot',0,'Readiness traffic eligibility; restart semantics liveness/startup-এর সঙ্গে আলাদা।'],flow:['Desired Deployment','Scheduled Pods','Readiness + Service','Rollout / scale'],'ref':'https://kubernetes.io/docs/concepts/workloads/'});
add({m:'operations',id:'chaos',t:'Chaos engineering ও controlled failure drills',intro:'অজানা সময়ে ভাঙার অপেক্ষা না করে ছোট controlled experiment-এ recovery যাচাই করুন।',b:['Steady-state hypothesis লিখুন: “এক worker হারালেও accepted jobs deadline-এর মধ্যে শেষ হবে।” ছোট blast radius, observability, abort criteria ও rollback আগে ঠিক করুন। শুরু local/staging থেকে; production experiment আলাদা organizational controls চায়।','Fault injection হতে পারে process kill, latency, packet loss, dependency error, disk capacity বা credential expiry। Failure mode representative কি না এবং test itself কী damage করতে পারে বিচার করুন। Game day/runbook exercise মানুষের communication ও ownership-ও পরীক্ষা করে।'],ex:'Staging-এ report worker stop করুন। Queue age বাড়বে, accepted jobs থাকবে, restart-এর পর drain হবে—এই expected behaviour metric দিয়ে যাচাই করুন। শুধু worker online ফিরে আসা business recovery প্রমাণ নয়।',when:'Reliability assumptions ও incident readiness যাচাই।',trade:'Failure discovery value দেয়; uncontrolled experiment outage ও data loss ঘটাতে পারে।',err:'Production-এ random kill করাই chaos engineering বলা।',task:'Hypothesis, fault, metrics, abort condition, recovery ও findings নিয়ে এক-page drill report লিখুন।',mem:'Hypothesis দিন, blast radius ছোট রাখুন, recovery মাপুন।',q:['Failure drill-এর আগে কী ঠিক করা জরুরি?','Abort ও recovery criteria','শুধু tool logo','কেবল animation speed',0,'Controlled experiment-এ safety/verification boundaries দরকার।'],flow:['Steady-state hypothesis','Bounded fault','Observe + abort guard','Recover + learn']});
add({m:'engineering',id:'domain-design',t:'Domain design, bounded context ও maintainability',intro:'একই “customer” sales-এর কাছে lead, billing-এর কাছে payer—শব্দ একই হলেও model আলাদা হতে পারে।',b:['Domain design business capability ও language বুঝে boundary তৈরি করে। Bounded context-এর মধ্যে term/model-এর অর্থ পরিষ্কার থাকে। Aggregate related invariants-এর transaction boundary ভাবতে সাহায্য করে; সব entity এক বিশাল aggregate করবেন না।','Context map integration relationships দেখায়। Anti-corruption layer external/legacy model-কে নিজের domain-এ অনুবাদ করতে পারে। Module public interface, dependency direction, ownership ও documentation maintainability বাড়ায়। DDD মানেই microservices নয়; modular monolith-এও প্রয়োগ হয়।'],ex:'CRM lead delete মানে financial invoice record delete নয়। Billing payer identity reference রেখে নিজের retention ও audit rule অনুসরণ করবে।',when:'Complex business rules, multiple teams ও long-lived product।',trade:'Precise boundaries change isolation দেয়; অতিরিক্ত abstraction ও ceremonial modeling delivery ধীর করতে পারে।',err:'একটি table = এক domain/service; business expert-এর ভাষা না বোঝা।',task:'Booking, billing ও support-এর vocabulary ও dependency map লিখুন। কোন invariant কোথায় enforce হবে দেখান।',mem:'Business language দিয়ে boundary, folder দিয়ে নয়।',q:['DDD প্রয়োগে microservices বাধ্যতামূলক?','না','হ্যাঁ','শুধু SQL হলে',0,'Domain boundaries একটি monolith-এর module-এও থাকতে পারে।'],flow:['Business vocabulary','Bounded contexts','Invariants + ownership','Integration contract']});
add({m:'engineering',id:'testing-strategy',t:'Unit, integration, contract, acceptance ও performance tests',intro:'একটি function সঠিক আর পুরো booking journey সঠিক—এটি একই ধরনের পরীক্ষা নয়।',b:['Unit test ছোট business rule isolation-এ পরীক্ষা করে। Integration test real DB/provider boundary behaviour ধরে। Contract test consumer/provider interface expectation ধরে। End-to-end/acceptance tests critical user journey ও agreed criteria যাচাই করে। Security negative tests unauthorized path পরীক্ষা করে।','Representative performance tests-এ concurrency, arrival pattern, data size, duration, warm/cold state ও errors record করুন। Stress breaking point, soak দীর্ঘ সময়ের leak, spike sudden load দেখে। Invariant-based test outcome সঠিক কি না দেখে; শুধু HTTP200 count যথেষ্ট নয়। Test doubles real integration-এর বিকল্প নয়।'],ex:'Booking confirm-এর unit test price rule যাচাই করে। Real PostgreSQL concurrent test double booking ঠেকানো যাচাই করে। E2E patient booking flow দেখে। Expired token/other tenant access reject-এর negative tests আলাদা।',when:'Release confidence, architectural changes ও production regression prevention।',trade:'Broad E2E বাস্তব flow দেখে কিন্তু slow/flaky হতে পারে। Lower-level tests precise, integration gaps থাকতে পারে।',err:'Mock-এর behaviourকেই external provider guarantee ধরা; implementation হুবহু mirror করা।',task:'এক booking workflow-এর জন্য প্রতিটি test level-এর একটি meaningful case লিখুন।',mem:'সঠিক logic, সঠিক boundary, সঠিক journey—তিন স্তরে যাচাই।',q:['Database lock correctness যাচাইয়ের ভালো test?','Real DB concurrent integration test','শুধু mocked repository','শুধু screenshot',0,'Real isolation/constraint behaviour mock দিয়ে প্রমাণ হয় না।'],flow:['Risk / acceptance rule','Right test level','Repeatable data + failures','Evidence + release decision']});
add({m:'engineering',id:'cost',t:'Cost estimation, TCO ও unit economics',intro:'Server bill-ই পুরো খরচ নয়। Storage, traffic, licenses, operations ও মানুষজনের সময়ও লাগে।',b:['Total cost-এ compute hours, DB/storage/backup, network egress, managed service requests, logs, licenses ও operational labour আলাদা ধরুন। Cost model-এর unit, region, currency ও assumption স্পষ্ট লিখুন। এখানে example rates কাল্পনিক; live provider price নয়।','Unit economics: total relevant monthly cost / successful tasks। Idle baseline ও variable cost আলাদা রাখুন। Peak capacity, growth, retention ও disaster recovery যোগ করুন। Managed service-এর বেশি bill engineering effort কমাতে পারে; self-hosting-এর কম bill human operations cost বাদ দিলে misleading।'],ex:'কাল্পনিক: compute200 + DB100 + storage30 + egress70 + monitoring50 = 450 units/month। 90,000 successful job হলে infra cost/job0.005 units; support/labour বাদ থাকলে তা স্পষ্ট বলুন।',when:'Architecture comparison, budget এবং AI inference pricing।',trade:'Cost কমাতে caching/batching quality, latency ও freshness বদলাতে পারে।',err:'সর্বনিম্ন instance price-কে lowest TCO বলা।',task:'নিজের capstone-এর cost spreadsheet না বানিয়েও fixed/variable line items ও optimistic/base/peak scenarios লিখুন।',mem:'মাসিক bill + operations + প্রতি সফল কাজের খরচ।',q:['TCO-তে কোনটি বাদ দেওয়া ঠিক নয়?','Operational labour ও maintenance','শুধু logo color','শুধু filename',0,'পরিচালনার সময়/দক্ষতাও মোট মালিকানার খরচের অংশ।'],flow:['Workload assumptions','Fixed + variable costs','Operational TCO','Cost per successful task']});
add({m:'engineering',id:'documentation',t:'Design docs, ADR, runbooks ও external API docs',intro:'এক মাস পরে অন্য developer যেন আপনার সিদ্ধান্ত বুঝতে পারেন—documentation-এর কাজ সেটি সম্ভব করা।',b:['Design doc-এ problem, scope, non-goals, assumptions, diagram, APIs/schema, alternatives, failure/security/cost ও rollout রাখুন। ADR একটি সিদ্ধান্তের context, considered options, chosen option ও consequences সংক্ষিপ্ত ধরে। Diagram-এর arrows-এ protocol/data বোঝান।','Runbook incident symptom→checks→mitigation→recovery verification→escalation লিখে। API docs authentication, sample requests, errors, pagination, rate limits, idempotency ও version policy বোঝায়। User manual end-user task দিয়ে লেখা; internal implementation detail দিয়ে নয়। Docs ownership ও update trigger রাখুন।'],ex:'Redis cache যোগ করার ADR-এ measured read bottleneck, stale-data tolerance, alternatives ও outage fallback রাখুন। “Redis fast” একা সিদ্ধান্তের কারণ নয়।',when:'Team handover, integration, review ও incident response।',trade:'Detailed docs value দেয় কিন্তু stale হলে বিভ্রান্ত করে। Decision-focused docs রক্ষণাবেক্ষণ সহজ।',err:'Diagram থাকলেই design document complete; user guide-এ internal jargon ছড়ানো।',task:'একটি API timeout incident-এর runbook লিখে অন্য কাউকে follow করতে দিন।',mem:'কী বানালাম, কেন, ভাঙলে কী করব—লিখে রাখুন।',q:['ADR প্রধানত কী ধরে?','একটি সিদ্ধান্তের কারণ ও পরিণতি','সব source code','শুধু meeting attendance',0,'Decision record future reviewers-কে context দেয়।'],flow:['Problem + options','Decision / ADR','Operational runbook','Maintain with changes']});
add({m:'engineering',id:'ux',t:'UX, accessibility ও failure-state design',intro:'Backend কাজ করছে, কিন্তু user জানেন না request pending নাকি failed—সেটিও system-এর সমস্যা।',b:['Critical journeys-এ loading, empty, success, error, timeout ও retry state design করুন। Retry control idempotent intent preserve করবে। Async job accepted হলে progress/status দেখান। Accessibility-তে keyboard access, labels, readable contrast, focus ও reduced motion রাখুন।','Usability test-এ representative user task শেষ করতে পারেন কি না দেখুন। Performance perception skeleton/optimistic UI দিয়ে সাহায্য করতে পারে, কিন্তু false financial confirmation নয়। Sensitive permission errors user-কে যথেষ্ট তথ্য দেবে, অন্য tenant-এর resource existence অপ্রয়োজনে প্রকাশ করবে না।'],ex:'Report queued। User download button বারবার চাপছেন। Clear “processing” state ও stable job ID দিলে duplicate কাজ কমে; cancel করলে তা accepted নাকি already completed জানাতে হবে।',when:'Web/mobile user flows ও customer-facing delivery।',trade:'Rich feedback usability বাড়ায়; exact progress না জানা থাকলে fake percentage misleading।',err:'শুধু happy path design; red/green color দিয়েই ফল বোঝানো।',task:'Payment timeout-এর screen, retry action ও accessible status message লিখুন।',mem:'System-এর state user-এর কাছে সৎভাবে দৃশ্যমান হোক।',q:['Unknown payment outcome-এ UI কী দেখাবে?','Pending/verification status','নিশ্চিত paid অনুমান','যেকোনো random progress',0,'Outcome নিশ্চিত হওয়ার আগে success দাবি করবেন না।'],flow:['User intent','Honest pending state','Accessible feedback','Safe retry / recovery']});
add({m:'engineering',id:'migration',t:'Migration, interoperability ও SDLC',intro:'চলন্ত গাড়ির ইঞ্জিন বদলানোর মতো—পুরোনো ও নতুন অংশ কিছু সময় পাশাপাশি চলতে পারে।',b:['Migration-এর আগে source/target schema, identifier mapping, compatibility, data quality, downtime budget ও rollback boundary লিখুন। Backfill chunked ও restartable করুন; dual-write-এ partial failure হতে পারে। CDC/outbox/dual-read strategy-এর consistency ও operational cost আলাদা।','Expand-contract, shadow reads, reconciliation ও staged traffic cutover ব্যবহার করা যায়। Totals/checksums/sample validation দিয়ে data যাচাই করুন; row count একা semantic equality নয়। SDLC-এ requirements→design→review→implement→test→release→observe loop বজায় রাখুন। Legacy adapter interoperability রক্ষা করতে পারে।'],ex:'Old customer_id string, নতুন UUID। Mapping না রাখলে historical invoice link ভাঙবে। Backfill restart হলে duplicate create না করতে stable mapping ও idempotency লাগবে।',when:'Database/schema/provider change ও monolith extraction।',trade:'Parallel compatibility downtime কমাতে পারে, কিন্তু dual-system maintenance ও drift risk বাড়ে।',err:'Deploy rollback করলেই irreversible data transformation undo হবে।',task:'এক field split-এর phased migration, validation query এবং cutover abort criteria লিখুন।',mem:'Copy → verify → switch → observe → retire।',q:['Row count মিলে গেলে migration সঠিক নিশ্চিত?','না, semantic validation দরকার','হ্যাঁ','শুধু CSV হলে',0,'Relations, values ও business invariants-ও যাচাই করতে হবে।'],flow:['Compatibility + mapping','Backfill + reconcile','Staged cutover','Observe / rollback boundary']});
add({m:'engineering',id:'retention',t:'Data retention, deletion, audit ও backups',intro:'কোন data কতদিন থাকবে—এটি storage খরচ, privacy ও recovery তিনটিকেই বদলায়।',b:['Operational record, audit event, analytics, logs, files ও backups-এর retention আলাদা হতে পারে। Business/legal requirements দায়িত্বশীলভাবে নির্ধারণ করুন; এখানে কোনো jurisdiction-specific retention period ধরে দেওয়া হয়নি। Hot/warm/archive tier ও deletion schedule document করুন।','Soft delete user-visible removal হতে পারে, physical deletion নয়। Search index, cache, export, object copy ও backup lifecycle-এ deletion propagation ভাবুন। Restore-এর পরে deleted record আবার না ফেরা কীভাবে হবে তা policy করুন। Audit append-only history-তে sensitive payload অপ্রয়োজনে রাখবেন না।'],ex:'User profile delete হলেও invoice accounting record retain করতে হতে পারে—এটি applicable rule অনুযায়ী আলাদা সিদ্ধান্ত। Personal details minimize/pseudonymize করার প্রয়োজনও থাকতে পারে।',when:'Long-lived SaaS, sensitive files ও cost/recovery planning।',trade:'Long retention investigation সাহায্য করে, storage/privacy exposure বাড়ায়। Short retention reprocessing/recovery সীমিত করে।',err:'UI থেকে hide করাই সব system ও backup থেকে deletion।',task:'নিজের app-এর data classes, purpose, owner, retention, deletion ও restore behaviour table করুন।',mem:'কতদিন রাখব, কোথা থেকে মুছব, restore-এ কী হবে? ',q:['Soft delete কি সব physical copy মুছে দেয়?','না','হ্যাঁ','শুধু Redis থাকলে',0,'Copies/index/backups আলাদা lifecycle অনুসরণ করতে পারে।'],flow:['Classify data','Retention + access policy','Delete across projections','Backup expiry / restore rules']});
add({m:'cases',id:'rate-limiter-case',t:'Case study: distributed rate limiter',intro:'তিন API instance-এর পেছনে এক tenant-এর quota কীভাবে একসঙ্গে enforce করবেন?',b:['Scope: প্রতি API key/tenant নির্দিষ্ট rate ও burst। Gateway authenticated identity থেকে key নেয়। Shared Redis-এর atomic Lua/transaction-like operation refill/read/decrement মেলায়; local counters global exact quota দেয় না। Multi-region exact global quota latency/availability cost বাড়ায়।','API 429 response, retry guidance, quota headers ও abuse monitoring রাখুন। Redis unavailable হলে operation অনুযায়ী fail-open/closed নির্ধারণ করুন। Limiter policy/config version এবং trusted proxy IP handling দরকার। Client-provided identity blind trust নয়।'],ex:'Tenant limit ১০০/minute। প্রতিটি server local১০০ দিলে তিনটিতে মোট৩০০ accepted হতে পারে। Shared atomic budget global quota-এর একটি implementation path; distributed failure semantics পরীক্ষা করতে হবে।',when:'Public SaaS API, login এবং expensive AI tasks।',trade:'Central limiter precise policy দেয় কিন্তু latency ও dependency; local admission fast কিন্তু approximate aggregate।',err:'GET balance তারপর আলাদা SET decrement দিয়ে race তৈরি।',task:'Requirement→key→algorithm→atomic operation→failure→metrics ছয় অংশে design doc লিখুন।',mem:'Global quota চাইলে shared coordination-এর দাম আছে।',q:['তিন instance-এ independent 100/min counters global100 দেয়?','না','হ্যাঁ','শুধু round robin-এ',0,'Aggregate quota instance সংখ্যা অনুযায়ী বাড়তে পারে।'],flow:['Verified tenant key','Shared atomic bucket','Allow / 429','Audit + failure policy'],'lab':'token'});
add({m:'cases',id:'notifications',t:'Case study: notification system',intro:'এক event থেকে email, SMS ও push—প্রতিটি channel-এর quota, delay ও failure ভিন্ন।',b:['Scope: transactional বনাম marketing, user preferences, templates, priorities ও delivery status। Durable acceptance-এর পরে channel queues, workers ও provider adapters। Stable notification/event ID দিয়ে duplicate local job কমান; provider idempotency থাকলে ব্যবহার করুন। “Exactly once delivery” external provider/user device পর্যন্ত blanket guarantee নয়।','Rate limits, retries, DLQ, quiet hours/consent rules যেখানে প্রযোজ্য সঠিক configuration, unsubscribe, provider status callback verification ও reconciliation রাখুন। High-priority OTP/critical transaction low-priority bulk pool থেকে isolate করুন।',],ex:'Order confirmation event তিনবার আসে। Unique(event_id,user_id,channel) local jobs dedup করতে পারে। Provider timeout-এর পরে status unknown; duplicate send risk policy অনুযায়ী handle করুন।',when:'Multi-channel communication ও background pipeline case।',trade:'Fallback delivery probability বাড়ায়, user-কে multiple channels-এ duplicate contact করতে পারে।',err:'Provider accepted মানেই recipient পড়েছেন।',task:'Accepted, provider_sent, delivered, failed, read—available channel অনুযায়ী state ও source লিখুন।',mem:'Accepted → sent → delivered → read আলাদা milestone।',q:['Provider HTTP200 কি user read-এর প্রমাণ?','না','হ্যাঁ','Push হলে সবসময়',0,'Provider acceptance ও end-user reading আলাদা।'],flow:['Event + preferences','Channel queues','Provider adapters','Callbacks / reconciliation'],'lab':'queue'});
add({m:'cases',id:'scheduler',t:'Case study: distributed job scheduler',intro:'কোন সময়ে job তৈরি হবে আর কোন worker execute করবে—দুটি দায়িত্ব আলাদা রাখুন।',b:['Schedule table recurrence/timezone ধরে; due occurrences থেকে unique(schedule_id,scheduled_for) run তৈরি করুন। Worker claim transaction-এ SKIP LOCKED-এর মতো mechanism ব্যবহার করতে পারে। Claim lease, heartbeat, fencing token ও deadline policy দরকার। DB-specific isolation/query semantics verify করুন।','Worker crash-এর পরে expired lease job পুনরায় eligible হতে পারে। External side effect idempotent/reconcilable করতে হবে। Long run overlap চলবে কি না, daylight saving/timezone, misfire/backfill ও cancellation define করুন। “Run once per schedule” unique run record; side effect exactly once-এর universal guarantee নয়।'],ex:'Daily report ৯টায় একবার। দুই scheduler একই occurrence দেখে insert করলেও unique constraint এক run record রাখে। Worker কাজ করে ack-এর আগে crash হলে replay side effect আলাদা সামলাতে হয়।',when:'Recurring reports, digests, batch pipelines।',trade:'DB-backed scheduler simple but polling/claim contention আছে; more distributed scheduler operations বাড়ায়।',err:'প্রতিটি app instance-এ cron চালিয়ে duplicate run না ভাবা।',task:'Scheduler A/B race, worker expiry ও late completion-এর sequence আঁকুন।',mem:'এক occurrence, এক run identity; execution recoverable।',q:['Unique run row মানেই external email exactly once?','না','হ্যাঁ','শুধু cron হলে',0,'Side effect execution failure boundary আলাদা।'],flow:['Schedule occurrence','Unique run creation','Lease + fenced worker','Retry / reconcile']});
add({m:'cases',id:'ridesharing',t:'Case study: ride matching ও geospatial search',intro:'নিকটবর্তী driver খোঁজা আর একই driver-কে একসঙ্গে দুই rider-এ assign না করা আলাদা সমস্যা।',b:['Scope: location updates, nearby search, request, offer/accept, trip state। Location store time-bounded index ধরে; stale driver বাদ দিন। Geohash grid কাছাকাছি cell খোঁজায় সাহায্য করে, কিন্তু cell boundary-তে neighbour search ও exact distance/ETA rerank লাগে। Dense region-এ quadtree adaptive subdivision বোঝার মতো।','Match eligibility, offer expiry, cancellation ও driver claim atomicভাবে enforce করুন। Push location eventually updated হতে পারে; final trip assignment authoritative state-এ। GPS noisy, location sensitive; retention ও access সীমিত করুন। Surge pricing product policy, magical ML requirement নয়।'],ex:'Nearest cell-এর driver দূরে, পাশের cell-এর driver আসলে কাছে। Neighbour cells candidate এনে actual distance/ETA compare করলে edge problem কমে।',when:'Geospatial indexing, realtime updates ও concurrency case।',trade:'ছোট cells candidate কমায় কিন্তু neighbours/frequent movement update বাড়ায়। Coarse cell noise বাড়ায়।',err:'Euclidean nearest-ই road ETA best; stale online status-এ driver assign।',task:'Cell boundary-তে rider ও তিন driver এঁকে candidate/rerank/atomic claim flow লিখুন।',mem:'Candidate search দ্রুত; final match সঠিক।',q:['Geohash একই cell-এর বাইরের driver কখনো nearer হতে পারে?','হ্যাঁ','না','শুধু HTTP3-এ',0,'Cell boundary nearest-neighbour search-এ adjacent cells জরুরি।'],flow:['Location + freshness','Geo candidates','Distance / ETA rank','Atomic assignment']});
add({m:'cases',id:'video-streaming',t:'Case study: video upload, HLS ও adaptive bitrate',intro:'একটি বড় video file upload করলেই সব network-এ smooth playback হয় না।',b:['Upload→verify/scan→transcode jobs→multiple resolutions/bitrates→segments+manifest→object storage+CDN। HLS/DASH ধরনের adaptive streaming-এ player network/buffer দেখে representation বেছে নিতে পারে। Transcoding CPU/GPU-intensive; ingestion ও playback plane আলাদা scale করুন।','Metadata ready state কেবল প্রয়োজনীয় processing শেষে দিন। Duplicate job idempotent output path ও version দিয়ে সামলান। Signed access, content rights, moderation, thumbnail, captions ও failure/reprocess policy scope অনুযায়ী রাখুন। Live streaming-এর latency/segment duration trade-off on-demand-এর থেকে আলাদা।'],ex:'User low bandwidth-এ 1080p ধরে রাখলে buffer হয়; 480p representation-এ switch করলে playback চলতে পারে। Short segment দ্রুত adapt করতে পারে কিন্তু request/encoding overhead বাড়ায়।',when:'Media platform, asynchronous processing ও CDN case।',trade:'More variants quality/flexibility দেয়; encoding/storage/egress খরচ বাড়ে।',err:'Transcode pending video-কে ready দেখানো; codec/container/bitrate এক মনে করা।',task:'এক video processing fail হলে metadata state, retry ও incomplete outputs cleanup design করুন।',mem:'একবার upload, বহু representation, user অনুযায়ী delivery।',q:['Adaptive bitrate player কী অনুযায়ী variant বদলাতে পারে?','Network ও buffer condition','শুধু filename length','DB shard count',0,'Playback health অনুযায়ী quality adjust হয়।'],flow:['Upload + validation','Transcode workers','Segments + manifest','CDN → adaptive player']});
add({m:'cases',id:'autocomplete',t:'Case study: search autocomplete, trie ও ranking',intro:'Prefix মিলে গেলেই best suggestion নয়; popularity, freshness, language ও permission-ও প্রভাব ফেলে।',b:['Trie prefix navigation-এ সাহায্য করে; প্রতি prefix-এ top-k precompute করলে reads cheap হতে পারে, updates ও memory বাড়ে। Search-engine edge n-gram/inverted index অন্য approach। Unicode normalization, Bangla/Banglish variant, typo handling ও locale-aware rules define করুন।','Client debounce, cancellation, min prefix length, server quota ও short-TTL cache দিন। Analytics logs-এ sensitive query data minimize করুন। Personal/private suggestions-এর permission filter দরকার। Delete/update propagated না হলে stale sensitive content ফিরতে পারে।'],ex:'“ঢা” লিখলে ঢাকার relevant query ফেরে। Banglish “dhaka” বাংলা suggestion-এর সঙ্গে map হবে কি না product decision। Prefix result কপি করে সব tenant-এ cache করা নিরাপদ নয়।',when:'Search box, command palette ও entity lookup।',trade:'Precomputed top-k read latency কমায়; rank updates, index rebuild ও memory খরচ বাড়ে।',err:'Trie থাকলেই fuzzy search/semantic ranking হয়ে যায়।',task:'Prefix index ও top-k update flow লিখুন। Permission change-এর পরে cached suggestion invalidation দেখান।',mem:'Prefix candidate আনে; ranking ও permissions ফল ঠিক করে।',q:['Trie নিজে কী সবসময় করে না?','Semantic relevance ও fuzzy matching','Prefix traversal','Key path organization',0,'Additional algorithms/data লাগতে পারে।'],flow:['Normalized prefix','Prefix / search index','Rank + permission','Cached suggestions']});
add({m:'cases',id:'payments-ledger',t:'Case study: payments, double-entry ledger ও reconciliation',intro:'Payment provider-এর status আর নিজের accounting record আলাদা system; দুটো নিয়মিত মেলাতে হয়।',b:['Scope: payment intent, authorization/capture/refund, immutable journal ও reporting। Amount/currency precise representation ব্যবহার করুন। Double-entry journal-এ প্রতিটি transaction-এর debit/credit balance হয়; অর্থ কোথা থেকে কোথায় গেল তা account structure অনুযায়ী record করুন। Balanced entry alone correct business amount/provenance প্রমাণ নয়।','Idempotency key, provider reference unique constraints, verified webhooks, pending states, settlement/reconciliation jobs ও audit controls রাখুন। Webhook duplicate/out-of-order হতে পারে। Corrections সাধারণত compensating/reversing entries; history silently mutate নয়। এটি educational ledger model, jurisdiction-specific accounting advice নয়।'],ex:'Provider capture complete, webhook হারিয়েছে। Periodic status reconciliation local pending payment update করতে পারে। New charge দিয়ে “fix” করলে duplicate payment হয়। Refund success ও bank settlement timing আলাদা হতে পারে।',when:'Financial integration correctness ও senior-style failure reasoning।',trade:'Auditability ও correctness extra workflow, storage ও review চাইবে।',err:'Wallet balance শুধু mutable number, journal নেই; HTTP timeout-এ দ্বিতীয় charge।',task:'Capture success/response lost, duplicate webhook, partial refund—তিন scenario-র state ও journal লিখুন।',mem:'Intent এক, money trail স্পষ্ট, provider-এর সঙ্গে নিয়মিত মেলানো।',q:['Balanced ledger entry হলেই amount business-wise সঠিক?','না','হ্যাঁ','শুধু decimal হলে',0,'Balance arithmetic invariant; authorized correct transaction আলাদাভাবে verify হয়।'],flow:['Idempotent payment intent','Provider + verified events','Balanced journal','Settlement reconciliation']});
add({m:'career',id:'tradeoff-review',t:'Trade-off review ও mid বনাম senior depth',intro:'“এটাই best” বলার চেয়ে কোন constraint-এ কোন option ভালো তা ব্যাখ্যা করা বেশি শক্তিশালী।',b:['Decision compare করতে requirement, alternatives, latency/correctness/reliability/cost/complexity ও reversibility লিখুন। Measured constraint আর অনুমান আলাদা করুন। “১ লাখ user” একা microservices-এর কারণ নয়; peak workload ও team needs দেখুন।','Mid-level একটি service independently implement/operate করতে পারবেন। Senior broader system evolution, ownership boundaries, business impact ও incident learning-এ সিদ্ধান্ত নেন। সব consensus internals মুখস্থ seniority নয়। Decision record এবং failure evidence story তৈরি করুন।'],ex:'Managed queue bill বেশি, কিন্তু small team-এর on-call burden কমাতে পারে। Self-hosted broker-এর cloud bill কম হলেও operations skill/time ধরলে TCO অন্য হতে পারে।',when:'Design interview, PR/ADR review ও customer architecture discussion।',trade:'এক dimension optimize করলে অন্য dimension ক্ষতিগ্রস্ত হতে পারে; product priority দিয়ে বিচার করুন।',err:'Tool names-এর তালিকাকে reasoning বলা।',task:'Redis বনাম DB-only এবং monolith বনাম services—দুটি ADR-এ ৩টি alternative লিখুন।',mem:'Constraint → options → evidence → consequence।',q:['Trade-off statement-এর ভালো উদাহরণ?','Stale tolerance থাকায় cache নিই, invalidation cost মেনে','Redis fast তাই সবখানে','সবসময় Kafka',0,'সিদ্ধান্তের শর্ত ও খরচ দুটিই প্রকাশ পায়।'],flow:['Requirements','Alternatives','Evidence + consequences','Decision + revisit trigger']});
add({m:'career',id:'mock-booking',t:'Guided mock ১: appointment booking',intro:'এটি MCQ নয়—নিজে design করুন, তারপর reference reasoning-এর সঙ্গে মিলিয়ে দেখুন।',b:['Prompt: একাধিক clinic, practitioners ও time slots। Patients book/cancel করবে; double booking নিষিদ্ধ। প্রথমে timezone, capacity, payment scope, cancellation ও peak traffic জিজ্ঞেস করুন। API/schema লিখে availability path ও atomic reservation deep dive করুন।','Reference outline: tenant-aware API→PostgreSQL authoritative booking→outbox→notification worker। Cache শুধু indicative search। Unique/locking strategy, hold expiry, duplicate create, permission ও backup test আলোচনা করুন। Add sharding only after measured need। Rubric: requirements2, data correctness3, API2, failure2, communication1—মোট10।'],ex:'Interviewer বলেন “payment timeout হলো”। Good answer: outcome unknown, pending intent/idempotency/reconciliation। Blind retry new charge নয়।',when:'Mid-level correctness-focused mock practice।',trade:'সব feature cover-এর বদলে critical invariant-এ যথেষ্ট depth দিন।',err:'একটি database icon আঁকেই concurrency solved বলা।',task:'৪৫ মিনিটে নিজে design record করুন। Rubric দিয়ে score ও তিন learning gap লিখুন; score self-assessment।',mem:'প্রথম mock-এর কেন্দ্র: double booking হবে না কেন? ',q:['Booking mock-এর সবচেয়ে গুরুত্বপূর্ণ deep dive কোনটি?','Concurrent reservation correctness','Logo design','সব database product নাম',0,'Core business invariant আগে।'],flow:['Clarify + estimate','API/schema','Atomic reservation','Failures + rubric']});
add({m:'career',id:'mock-notification',t:'Guided mock ২: webhook delivery platform',intro:'Customer endpoint slow বা offline হলেও accepted event হারাবে না—এই প্রতিশ্রুতির design করুন।',b:['Prompt: producers event submit করবে; subscribers-এর HTTPS endpoint-এ delivery। Clarify ordering, retry window, payload retention, signatures, quotas ও delivery guarantees। Reference: authenticated ingestion→durable event/subscription record→queues→bounded workers→attempt log→DLQ/replay।','Signed webhook, endpoint ownership, SSRF/egress controls, retries/backoff+jitter, per-subscriber isolation ও idempotency ID দিন। Delivery at-least-once হলে receiver contract-এ duplicate handling লিখুন। Rubric: contract2, durability2, security2, overload2, recovery2।'],ex:'এক subscriber ৩০ সেকেন্ড অপেক্ষা করায় সব worker আটকে যাচ্ছে। Per-subscriber concurrency/timeouts ও bulkhead দিলে অন্য customers-এর delivery চলতে পারে।',when:'Async delivery, external integration ও FDE-type problem solving।',trade:'Long retry window recovery বাড়ায়; storage, delays ও user support load বাড়ে।',err:'Customer URL blindly fetch করে internal network access দেওয়া।',task:'আপনার design-এ ৫টি crash/timeout বসান; event state ও retry policy লিখুন।',mem:'Accept durable, deliver bounded, retry visible।',q:['এক slow subscriber-এর প্রভাব কীভাবে সীমিত করবেন?','Per-subscriber concurrency ও isolation','সব timeout unlimited','সব queue এক worker',0,'Resource isolation noisy neighbour problem কমায়।'],flow:['Durable ingestion','Tenant-aware scheduling','Signed bounded delivery','Attempt audit + replay']});
add({m:'career',id:'mock-chat',t:'Guided mock ৩: realtime chat ও offline sync',intro:'Conversation-এর message order এবং network disconnect-এর পর recovery—এই দুই বিষয় দিয়ে design যাচাই করুন।',b:['Prompt: one-to-one/group text chat, history, receipts, offline sync। Scope media/encryption/spam rules আলাদা করুন। Reference: auth/membership→connection gateways→persistent message store→routing events→recipient ack; last sequence cursor-এ catch-up।','Message ID dedup, per-conversation ordering, fan-out, presence TTL, slow clients, reconnect backoff ও delete/permission propagation আলোচনা করুন। Gateway memory history নয়। Rubric: state/ordering3, persistence2, reconnect2, scaling2, security1।',],ex:'Server stored message কিন্তু sender ack হারাল। Client same message ID retry করলে duplicate bubble নয়; existing authoritative result ফেরানো যায়।',when:'Realtime/mobile architecture interview।',trade:'Presence eventually consistent হতে পারে; confirmed message persistence-এর guarantee আলাদা।',err:'WebSocket connected মানেই delivered/read নিশ্চিত।',task:'দুই device, একটি crash ও একটি offline member-এর ৮-step sequence লিখুন। নিজের audio review করুন।',mem:'প্রেরণ, সংরক্ষণ, পৌঁছানো, পড়া—চারটি আলাদা ধাপ।',q:['Sender ack হারিয়ে retry করলে কোন identity কাজে আসে?','Stable client message ID','প্রতিবার নতুন random intent','CSS class',0,'একই logical message dedup করতে stable identity দরকার।'],flow:['Membership + message ID','Persist + sequence','Route + receipts','Reconnect catch-up']});
// Reorder by the displayed learning path; keep old IDs for imported progress.
const order=new Map(MODULES.map((m,i)=>[m.id,i]));LESSONS.sort((a,b)=>order.get(a.module)-order.get(b.module));
window.COURSE_VERSION='2.0';
// V2 questions use stable varied answer positions; V1 positions remain intact
// so an imported V1 progress file retains its original quiz answers.
LESSONS.filter(l=>l.newInV2).forEach(l=>{const k=[...l.id].reduce((n,c)=>n+c.charCodeAt(0),0)%3;const o=l.quiz.o;l.quiz.o=o.slice(k).concat(o.slice(0,k));l.quiz.a=(l.quiz.a-k+3)%3;});
// Additional depth for concepts that were only briefly introduced in V1.
const deepen={
'protocol-choice':'Serialization-এ JSON human-readable ও broad tooling দেয়; protobuf typed schema ও compact encoding দিতে পারে, কিন্তু field-number/schema compatibility রক্ষা করতে হয়। Compression যেমন gzip/Brotli bytes কমায় কিন্তু CPU ও latency খরচ যোগ করে; already-compressed media-তে লাভ কম হতে পারে। Payload size, parse time ও compress cost মেপে সিদ্ধান্ত নিন।',
'replication':'Replication topology আরও আছে: multi-leader-এ একাধিক leader writes নেয়, concurrent conflicts ও conflict resolution দরকার। Leaderless-style store একাধিক replica-তে read/write policy চালাতে পারে; quorum/repair rules গুরুত্বপূর্ণ। Single-leader-এ write ordering সহজ হতে পারে, কিন্তু leader failover/throughput bottleneck আসে। Topology নাম alone durability guarantee নয়।',
 'transactions':'Isolation levels গভীরে: Read Committed-এ statement ভেদে committed snapshot বদলাতে পারে; Repeatable Read stable snapshot দেয় কিন্তু সব write-skew anomaly প্রতিরোধের guarantee product-independent নয়। Serializable সমতুল্য serial outcome-এর লক্ষ্য নেয়, conflict-এ transaction abort/retry করতে পারে। Read Uncommitted-এর exact implementation product-specific। Deadlock হলে consistent lock order, short transaction এবং whole-transaction retry policy দেখুন।',
'indexes':'Composite index order-এর সঙ্গে selectivity ও sort direction বিবেচনা করুন। Covering/index-only scan-এর সুযোগ engine/visibility অনুযায়ী বদলায়। Unbounded offset scan, non-sargable function predicate ও N+1 round trip আলাদা performance problem। Data encoding, wide rows ও unnecessary selected columns memory/network cost বাড়ায়।',
'recovery':'Disaster recovery-তে cold standby কম চলতি খরচ কিন্তু restore ধীর; warm standby কিছু infrastructure প্রস্তুত রাখে; hot/active setup দ্রুত recovery দিতে পারে কিন্তু replication/coordination খরচ বেশি। Multi-region active-active-এ conflicting writes, traffic cutover, identity ও shared dependencies পরীক্ষা ছাড়া availability দাবি করবেন না। RPO/RTO business journey অনুযায়ী নির্ধারণ করুন।',
'latency':'Load generation-এ closed-loop concurrency আর open-loop arrival rate এক নয়। Slow response হলে closed-loop client নিজে request কম পাঠাতে পারে, overload আড়াল হয়। Benchmark-এ arrival model, warmup, achieved throughput, timeout/error ও percentile distribution লিখুন। Coordinated omission-এর মতো measurement bias সম্পর্কে পরিচিত হন।',
'ids':'Encoding identity-কে ছোট representation করতে পারে: Base62 সংখ্যা encode করে, encryption নয়। Short code guess করা সম্ভব; authorization-এর বিকল্প নয়। Unique random ID collision probability কমায়, কিন্তু correctness-critical storage-এ unique constraint ও bounded collision retry থাকলে defence বাড়ে।',
'web-threats':'Encryption at rest, backup encryption ও key management transport TLS-এর থেকে আলাদা। Least privilege, rotation, audit ও compromised-key response লিখুন। Encryption sensitive data read করার অনুমতি নির্ধারণ করে না; authorized service decrypt করতে পারলে তার access policy-ও ঠিক থাকতে হবে।',
'monolith':'Maintainability-তে module ownership, small explicit interfaces, dependency review, readable code ও automated checks গুরুত্বপূর্ণ। Performance-critical path-এ suitable data structures যেমন hash-map lookup, heap priority queue ও trie prefix lookup cost আলাদা। Big-O input growth বোঝায়, constant factors/cache/IO বাস্তব measurement-এ আসে।',
'files':'Retention lifecycle tiering, file checksum/integrity verification ও restore test যোগ করুন। Client-provided filename/object key trusted নয়; server-generated scoped key ব্যবহার করুন। Download URL-এর expiry access revoke-এর exact behaviour backend/CDN policy দিয়ে যাচাই করতে হবে।'
};
Object.entries(deepen).forEach(([id,text])=>LESSONS.find(l=>l.id===id).body+='\n'+text);
GLOSSARY.push(['PACELC','Partition-এ availability/consistency, normal path-এ latency/consistency trade-off ভাবার lens।'],['BFF','Backend for Frontend; নির্দিষ্ট client-এর জন্য aggregation/adaptation।'],['LSM tree','Memory ও sorted disk files/compaction-ভিত্তিক storage design family।'],['Bloom filter','Membership filter: false positive হতে পারে; সঠিক implementation-এ false negative নয়।'],['mTLS','দুই peer-এর certificate-based transport identity ও encryption।'],['Fencing token','পুরোনো owner-এর write reject করার monotonically increasing token।'],['Raft','Non-Byzantine consensus protocol: terms, majority, log replication ও commit rules।'],['2PC','Prepare ও final decision-এ distributed atomic commitment protocol।'],['CQRS','Write model ও read model-এর দায়িত্ব আলাদা করা।'],['CDC','Change Data Capture; source data changes downstream-এ নেওয়া।'],['Virtual node','এক physical node-এর একাধিক hash-space position।'],['Hysteresis','একই threshold-এর পাশে ঘনঘন up/down না করতে আলাদা/stabilized response policy।'],['Cold start','নতুন process/function/model ready হওয়ার initialization delay।'],['TCO','Infrastructure, licensing, operations ও labour মিলিয়ে মোট মালিকানা খরচ।'],['ADR','একটি architecture decision-এর context, options ও consequences-এর record।'],['Geohash','Geographic coordinate-কে spatial cell representation-এ encode করার পদ্ধতি।'],['HLS / ABR','Segmented streaming ও network/buffer অনুযায়ী bitrate বদলানোর পদ্ধতি।'],['DLQ replay','Failed message inspect/repair করে controlledভাবে আবার process করা।'],['Write amplification','এক logical write-এর জন্য মোট physical/data-system writes-এর বৃদ্ধি।'],['Data lineage','Dataset/model/projection কোন source ও transformation থেকে এসেছে তার trace।']);

LESSONS.find(l=>l.id==='realtime').body+='\nShort polling প্রতিবার দ্রুত result নেয়; long polling-এ server নতুন event বা timeout পর্যন্ত request ধরে রাখে, response-এর পরে client আবার connection/request করে। SSE persistent one-way event stream দেয়। Long-poll timeout, concurrent open requests ও reconnect storm server capacity-তে প্রভাব ফেলে।';
